def fmt(value):
    value=html.escape(value)
    value=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',value)
    return re.sub(r'`(.+?)`',r'<code>\1</code>',value)

def dual(vi,ja):
    return f'<div class="reading-vi" lang="vi">{vi}</div><div class="reading-ja" lang="ja">{ja}</div>'

def flow(n):
    parallel=n in {32,36,41,42,53,58}
    items=[]
    for i,node in enumerate(FLOWS[n].split('~'),1):
        vi,ja=node.split(' / ',1)
        marker='•' if parallel else f'{i:02d} →'
        items.append(f'<li><b>{marker}</b>'+dual(fmt(vi),fmt(ja))+'</li>')
    tag='ul' if parallel else 'ol'
    caption=dual('<p><strong>Phân biệt vai trò:</strong></p>','<p><strong>役割を分けて確認：</strong></p>') if parallel else dual('<p><strong>Lần theo các bước:</strong></p>','<p><strong>順にたどる：</strong></p>')
    return caption+f'<{tag} class="teaching-flow">'+''.join(items)+f'</{tag}>'

def comparison(n):
    rows=TABLES.get(n,'').splitlines()
    if not rows:return ''
    rendered=[]
    for i,row in enumerate(rows):
        tag='th' if i==0 else 'td'
        cells=[dual(fmt(a),fmt(b)) for a,b in (cell.split('|',1) for cell in row.split('~'))]
        rendered.append('<tr>'+''.join(f'<{tag}'+(' scope="col"' if i==0 else '')+f'>{cell}</{tag}>' for cell in cells)+'</tr>')
    return '<div class="teaching-table table-scroll"><table class="teaching-compare"><thead>'+rendered[0]+'</thead><tbody>'+''.join(rendered[1:])+'</tbody></table></div>'

def enhance(n,text):
    if n not in NOTES:return text
    match=re.search(r'(<section[^>]*id="p1"><h2.*?</h2>)(.*?)(</section>)',text,re.S)
    assert match,n
    soup=BeautifulSoup(match[2],'html.parser')
    previous=soup.select('.teaching-unit') or soup.select('div.card')
    units=[]
    custom={21:[('Vì sao cần bộ nhớ ảo?','仮想記憶の目的'),('Đổi địa chỉ theo page','ページでの変換'),('Page fault: điều gì xảy ra?','ページフォールトの流れ'),('Chọn trang và theo dõi lịch sử','置換と履歴')],22:[('Dữ liệu đi vào và đi ra','入力と出力'),('Từ kích thước đến số điểm','寸法から画素数へ'),('Chọn cách tạo kết quả','出力方式の選択'),('Tách các lớp của giao tiếp','接続の観点を分ける')]}
    for i,line in enumerate(NOTES[n].strip().splitlines()):
        vi,ja,analogy,analogy_ja=line.split('~')
        old=previous[i] if i<len(previous) else None
        heading=old.find('h3') if old else None
        title_v,title_j=custom[n][i] if n in custom else (heading.get('data-vi',heading.get_text()),heading.get('data-ja',heading.get_text()))
        anchor=f'lesson-{n}-'+('understand' if n in [21,22] else 'topic')+f'-{i+1}'
        title=f'<h3 id="{anchor}" data-vi="{html.escape(title_v,quote=True)}" data-ja="{html.escape(title_j,quote=True)}">{fmt(title_v)}</h3>'
        body=dual('<p>'+fmt(vi)+'</p>','<p>'+fmt(ja)+'</p>')
        body+='<aside class="teaching-analogy">'+dual('<strong>💡 Ví von:</strong><p>'+fmt(analogy)+'</p>','<strong>💡 身近な例：</strong><p>'+fmt(analogy_ja)+'</p>')+'</aside>'
        if n not in [21,22] and old:
            ref=old.select_one('.reference-body')
            if ref:reference=ref.decode_contents()
            else:
                if heading:heading.decompose()
                reference=old.decode_contents()
            body+='<details class="term-reference"><summary data-vi="Tra cứu thuật ngữ của phần này" data-ja="この部分の用語を確認">Tra cứu thuật ngữ của phần này</summary><div class="reference-body">'+reference+'</div></details>'
        units.append('<article class="card teaching-unit">'+title+body+'</article>')
    assert len(units)==4,n
    intro=dual('<p>Đọc cơ chế và ví von trước, lần theo sơ đồ, rồi tự giải ví dụ trước khi mở lời giải. Phần tra cứu giữ các định nghĩa ngắn để ôn lại sau khi đã hiểu.</p>','<p>仕組みと身近な例を読み、図で関係を追い、解説を開く前に例題を解きます。短い用語説明は理解後の確認に使ってください。</p>')
    simulation=Path(__file__).with_name('normalization_lab.html').read_text(encoding='utf-8') if n==30 else ''
    if n in (21,31,35,53):
        simulation=Path(__file__).with_name('concept_labs.html').read_text(encoding='utf-8').replace('__LESSON__',str(n))
    if n in (21,31,35):
        story=Path(__file__).with_name('beginner_labs.html').read_text(encoding='utf-8').replace('__LESSON__',str(n))
        simulation=simulation.replace('<div data-intro>',story+'<details class="story-advanced"><summary><span class="reading-vi" lang="vi">Học tiếp: thuật ngữ và mô phỏng có thể đổi dữ liệu</span><span class="reading-ja" lang="ja">次に学ぶ：用語とデータを変えられる操作例</span></summary><div data-intro>',1).replace('</article>','</details></article>',1)
    body='<div class="teaching-intro">'+intro+flow(n)+comparison(n)+'</div>'+simulation+''.join(units)
    if n in [21,22]:
        preserved=soup.select_one('.preserved-theory .reference-body')
        original=preserved.decode_contents() if preserved else match[2]
        reference_soup=BeautifulSoup(original,'html.parser')
        for heading in reference_soup.select('h3'):heading.name='h4'
        original=str(reference_soup)
        # Earlier detailed mechanisms remain available alongside the new teaching sequence.
        body+='<details class="term-reference preserved-theory"><summary data-vi="Đọc thêm phần cơ chế chi tiết" data-ja="詳しい仕組みも確認">Đọc thêm phần cơ chế chi tiết</summary><div class="reference-body">'+original+'</div></details>'
    text=text[:match.start()]+match[1]+body+match[3]+text[match.end():]
    a,b,steps,steps_ja,pitfall,pitfall_ja=EXAMPLES[n].split('~')
    example='<article class="card worked-example" id="worked-reasoning-'+str(n)+'"><h3 id="lesson-'+str(n)+'-worked-example" data-vi="Cùng giải từng bước" data-ja="順を追って解く">Cùng giải từng bước</h3>'+dual('<p>'+fmt(a)+'</p>','<p>'+fmt(b)+'</p>')
    example+='<details class="worked-reasoning"><summary data-vi="Mở lời giải từng bước" data-ja="手順ごとの解説を開く">Mở lời giải từng bước</summary>'+dual('<ol>'+''.join('<li>'+fmt(s)+'</li>' for s in steps.split('|'))+'</ol>','<ol>'+''.join('<li>'+fmt(s)+'</li>' for s in steps_ja.split('|'))+'</ol>')+'<aside class="worked-pitfall">'+dual('<strong>⚠ Dễ nhầm:</strong> '+fmt(pitfall),'<strong>⚠ 注意：</strong> '+fmt(pitfall_ja))+'</aside></details></article>'
    p2=re.search(r'(<section[^>]*id="p2"><h2.*?</h2>)(.*?)(</section>)',text,re.S)
    assert p2,n
    examples=BeautifulSoup(p2[2],'html.parser')
    for prior in examples.select('.worked-example'):prior.decompose()
    source_header=''
    if n==21 and not BeautifulSoup(text,'html.parser').select_one('.source-intro'):
        source=next(card for card in examples.select('.card') if 'ichibanyashashi' in card.get_text())
        source['class']=['card','source-intro']
        source_header=str(source)
        source.decompose()
    text=text[:p2.start()]+p2[1]+example+str(examples)+p2[3]+text[p2.end():]
    if source_header:text=re.sub(r'(<section[^>]*id="p1")',lambda m:source_header+m[1],text,count=1)
    if 'id="teaching-styles"' in text:
        text=re.sub(r'<style id="teaching-styles">.*?</style>',lambda m:'<style id="teaching-styles">'+CSS+'</style>',text,count=1,flags=re.S)
    else:text=text.replace('</head>','<style id="teaching-styles">'+CSS+'</style></head>',1)
    return text

# Worked cases: problem VI/JA, ordered reasoning VI/JA, misconception VI/JA.
EXAMPLES = {}
EXAMPLES[39] = 'Nhân viên gửi nhầm bảng lương cho người ngoài. Tách tài sản, đe dọa, điểm yếu và tác động CIA; không suy thêm sự cố chưa được nêu.~給与表を外部へ誤送信した。資産、脅威、弱点、CIAへの影響を整理する。~Tài sản là thông tin bảng lương; hành vi gửi nhầm là đe dọa do con người trong tình huống.|Tác động trực tiếp là người không có quyền có thể đọc: tính bí mật bị ảnh hưởng.|Điểm yếu cụ thể cần kiểm tra thêm, chẳng hạn kiểm soát người nhận. Đề không nói nội dung bị sửa hay dịch vụ ngừng nên không tự khẳng định hai việc đó.~資産は給与情報、誤送信は人的な脅威。|直接の影響は機密性。|具体的な弱点は確認が必要で、改ざんや停止は設問から断定しない。~Không biến một giả thuyết nguyên nhân thành sự thật đã biết.~推測した原因を確認済みの事実として扱わない。'
EXAMPLES[40] = 'Nhật ký cho thấy cùng mật khẩu phổ biến được thử trên rất nhiều ID. Phân biệt với việc dùng cặp ID–mật khẩu rò rỉ.~同じよくあるパスワードを多数のIDで試した。漏えいした組の利用と区別する。~Giữ mật khẩu cố định, thay ID là reverse brute force theo phân loại của bài.|Nếu dùng từng cặp ID–mật khẩu đã rò rỉ từ dịch vụ khác thì là password list attack.|Cả hai có thể liên quan xác thực nhưng dấu hiệu về cách chọn ứng viên khác nhau; dựa nhật ký được cho để phân loại.~パスワード固定・ID変更なので逆総当たり。|他サイトから漏れたIDとパスワードの組ならリスト攻撃。|候補の選び方という違いを根拠に判断する。~Không chọn DDoS chỉ vì thấy “nhiều”: cần có mục tiêu và cách gây gián đoạn tương ứng.~多数という語だけでDDoSと決めない。'
EXAMPLES[41] = 'A gửi nội dung chỉ B được đọc, đồng thời muốn B kiểm tra đúng A ký. Xác định bốn vai trò khóa trong mô hình cơ bản.~AがBだけに読ませ、BがAの署名を確認したい。基本モデルで各鍵の役割は。~Bí mật nội dung: mã hóa bằng khóa công khai B, B giải bằng khóa bí mật B.|Nguồn gốc và toàn vẹn: A tạo chữ ký bằng khóa bí mật A, B kiểm tra bằng khóa công khai A.|Kiểm tra khóa công khai có đúng thuộc chủ thể qua cơ chế chứng thư/tin cậy phù hợp; chữ ký không thay bước mã hóa.~秘匿はB公開鍵で暗号化しB秘密鍵で復号。|署名はA秘密鍵で生成しA公開鍵で検証。|公開鍵と主体の対応を確認する。署名は暗号化の代わりではない。~Công khai để kiểm tra chữ ký phải là của người ký A, không phải cứ dùng khóa của người nhận B.~署名検証には署名者Aの公開鍵を使う。'
EXAMPLES[42] = 'Đăng nhập dùng mật khẩu và trả lời câu hỏi bí mật. Hệ thống gọi đó là “hai bước”; đã là MFA chưa?~パスワードと秘密の質問で二段階ログインする。異なる二要素認証か。~Xếp mật khẩu vào loại điều biết; câu trả lời bí mật cũng là điều biết.|Có hai lần nhập nhưng chỉ một loại yếu tố. Không chứng minh đã dùng hai loại độc lập.|Ví dụ kết hợp mật khẩu với thiết bị sở hữu tạo hai loại khác nhau trong mô hình, rồi vẫn cần quản lý quyền sau đăng nhập.~両方とも知識要素に分類する。|入力が二回でも種類は一つ。|知識と所持などの異なる種類を組み合わせ、認可は別に管理する。~Đếm loại yếu tố, không đếm số màn hình hay ô nhập.~画面や入力欄の数で要素数を決めない。'
EXAMPLES[47] = 'Yêu cầu: người dùng hủy đơn chưa giao; phản hồi trong 2 giây với tải quy định trong đặc tả. Cần chuyển thành thiết kế và kiểm thử ra sao?~未発送注文の取消しと、仕様で定めた負荷で2秒以内の応答を求める。どう設計と確認へつなぐか。~Hủy đơn là chức năng; thời gian phản hồi kèm tải là yêu cầu phi chức năng.|Thiết kế màn hình và xử lý hủy, dữ liệu trạng thái, giao tiếp và cách hiện thực để đáp ứng hai mặt.|Kiểm thử đơn đủ điều kiện và không đủ điều kiện; đo thời gian trong đúng tải đã nêu. Không đổi điều kiện đo để làm đẹp kết quả.~取消しは機能、負荷条件付き応答時間は非機能。|画面、処理、状態データ、接続を設計する。|条件別の取消しと指定負荷での時間を検証する。~Một unit test chạy nhanh chưa chứng minh toàn hệ thống đạt yêu cầu tải.~単体の速度だけで全体の負荷要件達成を証明しない。'
EXAMPLES[48] = 'Sau sprint, khách muốn điều chỉnh sản phẩm; nhóm cũng nhận ra kiểm tra mã chậm. Hai phản hồi thuộc góc xem xét nào?~スプリント後に顧客が製品変更を求め、チームはコード確認の遅さに気付いた。~Phản hồi về phần sản phẩm và hướng ưu tiên được xem với các bên liên quan ở review.|Vấn đề cách phối hợp và kiểm tra trong nhóm là nội dung cải tiến ở retrospective.|Đưa quyết định thích hợp vào công việc tiếp theo và cách làm việc, không chỉ ghi “đã họp”.~成果と今後の製品の方向はレビュー。|チームの働き方はレトロスペクティブ。|次の項目と作業改善に結び付ける。~Một buổi demo không tự thay cho việc nhóm xem lại cách làm.~デモだけで働き方の振返りも済んだとは考えない。'
EXAMPLES[49] = 'Khách gửi đơn, hệ thống tính tổng rồi lưu đơn và trả xác nhận. Biểu diễn bằng DFD: đâu là xử lý, luồng và kho?~顧客から注文を受け計算し保存して確認を返す。DFDの要素へ分ける。~Khách là external entity; “đơn đặt hàng” là data flow đi vào hệ thống.|“Tính tổng/ghi nhận đơn” là process; “dữ liệu đơn hàng đã lưu” là data store.|Xác nhận là data flow trả ra khách. Đặt tên mũi tên theo dữ liệu, không chỉ ghi “bước tiếp”.~顧客は外部実体、注文情報は入力データフロー。|計算と登録はプロセス、保存する注文群はデータストア。|確認情報は外部へのデータフロー。~DFD không tự chỉ ra mọi thứ tự thực thi hoặc thời gian chờ.~DFDだけで全実行順や待ち時間まで表したと思わない。'
EXAMPLES[50] = 'Quyết định A OR B, hai ca (T,F) và (F,T). Theo mô hình xét giá trị logic, đã đủ cả hai nhánh quyết định chưa?~判定A OR Bに(T,F),(F,T)を与える。論理値で両方の判定結果を通るか。~Ca 1: T OR F = T. Ca 2: F OR T = T.|Mỗi biến có xuất hiện T và F trong dữ liệu, nhưng cả hai kết quả quyết định đều T.|Muốn có nhánh F cần (F,F). Khi áp dụng vào mã thật còn phải xét quy tắc short-circuit của ngôn ngữ.~一つ目も二つ目も判定全体は真。|各入力値の真偽と全体の分岐を区別する。|偽の分岐には(F,F)が必要。実コードでは短絡評価も確認する。~Condition coverage theo mô hình không tự suy ra decision coverage.~条件の真偽から判定全体の網羅を自動では導けない。'
EXAMPLES[52] = 'Dự án đang có ngân sách và ngày bàn giao đã duyệt. Khách đề nghị thêm chức năng báo cáo. Nên xử lý gì trước khi hứa giữ nguyên mọi thứ?~予算と納期が承認済みの案件へ追加レポートを依頼された。約束の前に何をするか。~Làm rõ yêu cầu mới và nó có thuộc phạm vi đã thống nhất không.|Ước lượng ảnh hưởng công việc, phụ thuộc, người, thời gian, chi phí và chất lượng.|Trình quyết định theo thẩm quyền rồi cập nhật kế hoạch và thông báo. Không lặng lẽ thêm việc mà vẫn báo mọi chỉ tiêu như cũ.~要求を明確にして合意済み範囲を確認する。|作業、依存、資源、日程、費用、品質への影響を評価する。|権限に従って判断し計画と情報共有へ反映する。~Thay đổi có thể hợp lý, nhưng cần quản lý ảnh hưởng chứ không coi là miễn phí.~変更を拒むことが目的ではなく、影響を統制する。'
EXAMPLES[53] = 'PV=100, EV=80, AC=100, cùng đơn vị tiền. Tính CV, SV, CPI, SPI và giải thích thay vì chỉ ghi số.~PV100、EV80、AC100でCV、SV、CPI、SPIと意味を求める。~CV=80−100=−20: giá trị công việc hoàn thành thấp hơn tiền đã chi; CPI=80/100=0,8.|SV=80−100=−20: giá trị hoàn thành thấp hơn kế hoạch; SPI=80/100=0,8.|Hai góc đều không thuận lợi ở mốc này. SV không có đơn vị ngày, không kết luận “trễ 20 ngày”.~CVは−20、CPIは0.8で費用面は不利。|SVは−20、SPIは0.8で予定より出来高が少ない。|SVは金額単位で、20日遅れという意味ではない。~PV và AC bằng nhau không chứng minh đúng tiến độ hay đúng ngân sách về hiệu suất: còn phải xét EV.~PVとACの一致だけでは成果に対する効率は評価できない。'
EXAMPLES[54] = 'Ứng dụng ngừng; chuyển sang máy dự phòng giúp dùng lại, nhưng lỗi máy chính chưa rõ. Phân biệt công việc còn lại.~アプリ停止後に予備機で復旧したが、主系の原因は不明。活動を分ける。~Phục hồi dịch vụ bằng máy dự phòng là mục tiêu incident management; đây có thể là workaround.|Problem management tiếp tục điều tra nguyên nhân để giảm tái diễn.|Nếu cần sửa cấu hình hoặc phiên bản, thay đổi và triển khai phải được kiểm soát; cập nhật hồ sơ và liên lạc người dùng.~予備機での再開はインシデント管理の復旧。|原因究明と再発防止は問題管理。|必要な変更とリリースを管理し情報を更新する。~Dịch vụ chạy lại chưa chứng minh nguyên nhân gốc đã được xử lý.~再開と根本解決を同一視しない。'
EXAMPLES[55] = 'Người lập phiếu chi đồng thời tự duyệt bằng tài khoản thứ hai. Có hai tài khoản nhưng đã phân tách nhiệm vụ thực chất chưa?~支払登録者が別アカウントで自分の支払を承認する。実質的な職務分掌か。~Nhìn người kiểm soát thực tế, không chỉ tên tài khoản: cùng một người vẫn thực hiện cả hai vai trò.|Mục tiêu kiểm tra chéo và hạn chế tự tạo–tự duyệt chưa đạt chỉ bằng đổi tài khoản.|Kiểm toán cần căn cứ về phân quyền và hoạt động thực tế rồi báo phát hiện, để bên có trách nhiệm thực hiện cải tiến.~実際の操作主体が同一人物なら役割は分かれていない。|アカウントの数だけでは相互確認を実現しない。|権限と実績の証拠で評価し、管理側の改善へつなぐ。~Tài liệu có hai ô ký cũng chưa chứng minh có hai người độc lập kiểm tra.~署名欄が二つあることだけを実効性の証拠にしない。'
EXAMPLES[57] = 'Theo định nghĩa đề: ROI=lợi nhuận ròng/vốn đầu tư. Đầu tư 200, lợi nhuận ròng 50. Vì sao ROI là 25% mà không trừ vốn thêm lần nữa?~ROIを純利益÷投資額と定義する。投資200、純利益50ならなぜ25%か。~Nhận đúng đại lượng: 50 đã là lợi nhuận ròng, không phải doanh thu trước chi phí.|Thay định nghĩa: 50/200×100%=25%.|So phương án vẫn cần xem TCO, rủi ro và thời kỳ tính. Chỉ số này không bao gồm mọi mặt của quyết định đầu tư.~50はすでに純利益であり売上ではない。|定義に従い50÷200×100%=25%。|費用全体、リスク、評価期間も別に確認する。~Không tự đổi định nghĩa ROI hoặc trừ 200 khỏi một số đã được gọi là lợi nhuận ròng.~設問の利益の定義を勝手に変えない。'
EXAMPLES[58] = 'Doanh nghiệp có kỹ sư giỏi, quy trình bán hàng chậm, thị trường đang tăng nhu cầu nhưng xuất hiện đối thủ mới. Xếp SWOT có căn cứ.~技術者が優秀、販売手続が遅い、需要増加、新競合参入をSWOTへ分類する。~Kỹ sư giỏi và quy trình chậm đều nội bộ: lần lượt là S và W với mục tiêu đang xét.|Nhu cầu tăng và đối thủ mới đều bên ngoài: lần lượt là O và T theo tình huống.|Sau phân loại mới xét hành động: dùng thế mạnh để khai thác cơ hội và xử lý điểm yếu/rủi ro, không dừng ở điền bốn ô.~技術力と遅い手順は内部のSとW。|需要と競合は外部のOとT。|整理を具体的な対応の検討へ結び付ける。~Không xếp kỹ sư thành cơ hội chỉ vì đó là điều thuận lợi; còn phải xét nội/ngoại.~有利というだけでOにせず内外も判定する。'
EXAMPLES[59] = 'Sản xuất 10 sản phẩm, mỗi sản phẩm cần 2 linh kiện. Có sẵn 6 linh kiện dùng được, không có nhận hàng dự kiến hay hao hụt. Nhu cầu mua thêm?~10製品に各2部品、利用可能在庫6、入荷予定と損耗なし。追加必要数は。~Nhu cầu gộp = 10×2=20 linh kiện, từ kế hoạch và cấu thành sản phẩm.|Trừ tồn có thể dùng 6: nhu cầu ròng = 14.|Phải xét đúng giả thiết về tồn, nhận dự kiến và các điều kiện khác nếu đề thêm; đây là ví dụ nhu cầu, chưa tính lịch giao.~総所要量は10×2＝20。|利用可能在庫6を引き14。|入荷予定などの追加条件があれば反映し、数量と日程を分ける。~Không nhân 10 với tồn 6: tồn kho không phải định mức cấu thành.~在庫を製品一個の必要部品数と混同しない。'
EXAMPLES[60] = 'Giá bán 50, biến phí đơn vị 30, định phí 1000. Tính số lượng hòa vốn trong mô hình không thuế và chỉ bán một loại hàng.~単価50、単位変動費30、固定費1000。税なし一商品の損益分岐数量は。~Mỗi sản phẩm góp 50−30=20 để bù định phí.|Cần 1000/20=50 sản phẩm để đóng góp đủ 1000.|Kiểm chứng: doanh thu 2500; tổng chi phí 1000+50×30=2500; lợi nhuận bằng 0.~一個当たりの限界利益は20。|固定費1000÷20で50個。|売上2500、費用も1000+1500=2500で利益ゼロ。~Không lấy 1000/50: cần trừ biến phí trước khi xét phần đóng góp bù định phí.~売価全額を固定費回収に使えると考えない。'
EXAMPLES[61] = 'Một danh sách dùng mã thay tên, nhưng đơn vị giữ bảng nối mã với người và có thể đối chiếu dễ dàng. Chỉ đổi tên thành mã đã chứng minh không còn thông tin cá nhân chưa?~氏名をコードに置換したが、保有者は対応表で容易に照合できる。それだけで個人情報性を否定できるか。~Không chỉ nhìn cột tên; xét khả năng nhận biết người từ thông tin và việc đối chiếu theo điều kiện nguồn chính thức.|Trong tình huống đã cho, vẫn dễ nối lại tới cá nhân nên không dùng việc đổi mã làm bằng chứng duy nhất để loại trách nhiệm bảo vệ.|Giữ cách đánh giá theo khái niệm và phạm vi bài; tình huống pháp lý cụ thể còn phải đối chiếu đầy đủ các điều kiện.~氏名列の有無だけでなく識別と容易な照合を確認する。|容易に本人へ対応できるため置換だけでは根拠にならない。|個別の法的結論は必要な条件を別に確認する。~Mã hóa, đổi mã và ẩn danh không phải những từ có thể thay thế tùy ý.~暗号化、符号の置換、匿名化を無条件に同義としない。'
EXAMPLES[14] = 'Một Customer có thể chưa có đơn hoặc có nhiều Order; mỗi Order bắt buộc thuộc một Customer. Đọc hai đầu quan hệ thế nào?~顧客は注文が0件以上、一つの注文は必ず一顧客に属する。関連の両端はどう読むか。~Đứng ở một Customer, nhìn đầu Order: số đối tượng tương ứng là 0..*.|Đứng ở một Order, nhìn đầu Customer: phải có đúng 1.|Ghi Customer 1 — Order 0..*; đây là cấu trúc, không phải thứ tự tạo đối tượng.~一顧客から注文側を見ると0..*。|一注文から顧客側を見ると必ず1。|Customer 1 — Order 0..*で、生成順序を示すものではない。~Không đọc số 1 bên Customer thành “một khách chỉ có một đơn”.~顧客側の1を「顧客は一件しか注文できない」と逆に読まない。'
EXAMPLES[21] = 'Page có 1024 byte. Địa chỉ ảo 2500 thuộc page nào? Nếu page đó ở frame 5 thì địa chỉ vật lý là gì?~ページサイズ1024バイト、仮想アドレス2500。ページ番号と、対応フレームが5の場合の物理アドレスは。~Chia 2500 cho 1024: thương 2 là page, dư 452 là offset.|Tra page table: page 2 → frame 5. Chỉ thay phần số page.|Địa chỉ vật lý = 5×1024+452 = 5572 byte. Offset vẫn là 452.~2500÷1024の商2がページ番号、余り452が変位。|表でページ2に対応するフレーム5を取得する。|物理アドレスは5×1024+452＝5572。変位は変えない。~Không lấy 5+452, và không đổi offset thành số frame.~フレーム番号を単に足したり、変位を変更したりしない。'
EXAMPLES[22] = 'Một vùng in rộng 2 inch, cao 1 inch, mật độ 300 dpi ở cả hai chiều. Có bao nhiêu điểm? Nếu mỗi điểm 1 bit, dữ liệu thô bao nhiêu byte?~幅2インチ、高さ1インチ、両方向300dpi。画素数と1画素1ビットのデータ量は。~Chiều ngang: 2×300=600 điểm; chiều dọc: 1×300=300 điểm.|Tổng điểm = 600×300=180000. Mật độ được áp dụng cho từng chiều.|Dữ liệu = 180000 bit ÷8 = 22500 byte, bỏ phần đầu tệp theo mô hình.~横は600、縦は300画素。|総画素数は600×300＝180000。|1画素1ビットで180000÷8＝22500バイト。ヘッダは除く。~dpi không phải số điểm toàn vùng và cũng không phải số điểm mỗi giây.~DPIを総画素数や毎秒の点数と取り違えない。'
EXAMPLES[23] = 'Đang ở /school/fe/notes. Tìm file /school/fe/tests/22.html bằng đường dẫn tương đối, rồi tự kiểm tra bằng cách đi từng bước.~現在/school/fe/notesから/school/fe/tests/22.htmlへ相対パスでたどる。~Từ notes dùng .. đi lên /school/fe, không đi lên tận gốc.|Đi vào thư mục tests, rồi tới 22.html.|Kết quả ../tests/22.html. Ghép với mốc ban đầu và xử lý .. để kiểm chứng đúng đích.~..で/school/feへ一段上がる。|testsへ入り22.htmlを選ぶ。|../tests/22.html。現在位置と合わせて検証する。~Nếu đổi thư mục hiện tại thì phải giải lại; chuỗi tương đối không mang mốc gốc bên trong.~現在位置を変えたら再解釈する。相対パス自身は基準の場所を持たない。'
EXAMPLES[25] = 'Biểu mẫu có một phương thức thanh toán và hai lựa chọn thông báo độc lập. Chọn thành phần rồi nêu cách kiểm tra lỗi dễ hiểu.~支払方法は一つ、通知方法は二つを独立に選べるフォームを設計する。~Thanh toán là các lựa chọn loại trừ: cùng nhóm radio, chỉ một mục được chọn.|Email và thông báo ứng dụng có thể đồng thời: hai checkbox độc lập.|Nếu thiếu mục bắt buộc, ghi lỗi bằng chữ gần trường và cho người dùng bàn phím tới sửa; không chỉ tô màu.~支払方法は排他的なので同じグループのラジオボタン。|通知は両方選べるチェックボックス。|必須入力の不足は文字と位置で知らせ、キーボードでも修正できるようにする。~Không chọn checkbox chỉ vì nó có hình vuông đẹp hơn; kiểu chọn phải đúng quy tắc nghiệp vụ.~見た目ではなく選択の意味に合わせて部品を選ぶ。'
EXAMPLES[26] = 'PCM 8000 Hz, 16 bit/mẫu, 2 kênh, dài 5 giây. Bỏ header, không nén: cần bao nhiêu byte?~PCM8000Hz、16ビット、2チャネル、5秒。ヘッダなし非圧縮のバイト数は。~Mỗi kênh có 8000×5=40000 mẫu; hai kênh có 80000 giá trị mẫu.|Mỗi giá trị 16 bit: 80000×16=1280000 bit.|Đổi byte: 1280000÷8=160000 byte. Thời lượng tăng gấp đôi thì dung lượng cũng gấp đôi khi giữ các thông số khác.~一チャネル40000標本、二チャネルで80000標本。|16ビットを掛けて1280000ビット。|8で割り160000バイト。他の条件が同じなら時間に比例する。~Không chia 8 trước rồi lại coi kết quả còn là bit; ghi đơn vị ở mỗi dòng.~各段階で単位を記し、ビットとバイトを混ぜない。'
EXAMPLES[29] = 'Customer gồm C01 và C02. Order có O1→C01, O2→C01. Vì sao CustomerID trong Order không phải khóa của bảng Order?~顧客C01,C02、注文O1→C01とO2→C01がある。注文表のCustomerIDがキーでない理由は。~Cùng C01 xuất hiện ở hai đơn hợp lệ nên CustomerID không phân biệt duy nhất các hàng Order.|OrderID O1 và O2 phân biệt hai đơn; CustomerID giữ quan hệ tham chiếu tới Customer.|Một–nhiều được diễn tả bằng khóa ngoại lặp ở phía nhiều. C02 chưa có đơn vẫn là khách hợp lệ.~C01が複数の注文行に現れるので注文を一意に識別できない。|OrderIDで注文を識別しCustomerIDで顧客を参照する。|多側の外部キーは繰り返せる。注文のないC02も存在できる。~Khóa ngoại không mặc nhiên phải duy nhất trong bảng chứa nó.~外部キーはその表で必ず一意であるとは限らない。'
EXAMPLES[30] = 'R(OrderID, ProductID, ProductName, Qty), khóa (OrderID,ProductID). Quy định ProductID→ProductName và cả cặp xác định Qty. Tách để bỏ phụ thuộc bộ phận.~R(OrderID,ProductID,ProductName,Qty)、複合キー、ProductID→ProductName。部分従属を除く。~ProductName chỉ cần ProductID, không cần cả khóa: đây là thuộc tính bị phụ thuộc bộ phận.|Tạo Product(ProductID,ProductName); giữ Line(OrderID,ProductID,Qty).|ProductID ở Line tiếp tục liên kết Product. Hai dòng mua cùng sản phẩm dùng một nơi lưu tên sản phẩm.~ProductNameはキーの一部ProductIDだけで決まる。|ProductとLineへ分け、Qtyは複合キーの明細側へ残す。|ProductIDを結合に残し商品名の管理場所を一つにする。~Không chuyển Qty sang Product: số lượng thuộc từng lần mua, không phải cố định theo sản phẩm.~数量は購入明細ごとの値で、商品の固定属性ではない。'
EXAMPLES[31] = 'E(dept,salary) có (A,100),(A,200),(B,300),(B,400). Truy vấn GROUP BY dept HAVING SUM(salary)>500 cho những phòng nào?~Eが(A,100),(A,200),(B,300),(B,400)。部署別にSUM(salary)>500のグループを求める。~Không có WHERE nên giữ cả bốn hàng trước khi nhóm.|Nhóm A có tổng 300; nhóm B có tổng 700.|HAVING chọn nhóm tổng trên 500: chỉ B. Nếu lọc salary>500 ở WHERE trước, không hàng nào còn và kết quả khác.~WHEREがないので四行を残す。|Aの合計300、Bの合計700を計算する。|HAVINGでBだけ残す。集計前にsalary>500で絞るのは別の意味。~WHERE chọn hàng, HAVING chọn nhóm; không đổi chỗ chỉ vì cả hai đều có điều kiện.~行の条件とグループの条件を交換しない。'
EXAMPLES[32] = 'A có 100, B có 50. Chuyển 30 từ A sang B; lỗi xuất hiện sau khi trừ A nhưng trước khi cộng B. Kết quả nào phù hợp atomicity nếu chưa COMMIT?~A100、B50から30を振替え、A引落し後でB入金前に障害。未確定ならどうするか。~Trạng thái trung gian A=70,B=50 chưa đạt ý nghĩa chuyển tiền; tổng đã giảm không đúng nghiệp vụ.|ROLLBACK phần chưa xác nhận để trở về A=100,B=50 theo mô hình giao dịch.|Nếu cả hai cập nhật thành công và COMMIT thì A=70,B=80, tổng vẫn 150.~途中のA70,B50は取引の完成状態ではない。|未確定の変更を取り消しA100,B50へ戻す。|成功して確定した場合はA70,B80で総額150を保つ。~Atomicity không có nghĩa hai câu lệnh bắt buộc xảy ra cùng một thời điểm vật lý.~原子性を二命令の物理的な同時実行と考えない。'
EXAMPLES[33] = 'Bộ dữ liệu ảnh có nhãn mèo/chó dùng để học. Mô hình đúng 100% trên ảnh đã học nhưng kém trên ảnh mới. Phân loại vấn đề và cách đánh giá.~猫・犬のラベル付き画像で学習し、訓練画像は全問正解だが新画像に弱い。~Có nhãn đúng nên là học có giám sát; đầu ra là loại nên là bài toán phân loại.|Kết quả chênh lệch gợi ý overfitting; không kết luận mô hình tốt chỉ từ tập đã học.|Đánh giá bằng dữ liệu chưa dùng để học và kiểm tra cách chia, chất lượng dữ liệu. Không lấy đáp án tập đánh giá để luyện lại rồi vẫn gọi nó là độc lập.~教師ありの分類問題。|訓練と未知データの差から過学習を疑う。|未使用データと分割方法を確認し、評価情報を学習へ混ぜない。~Điểm luyện rất cao chưa tự cho biết khả năng khái quát.~訓練成績だけでは汎化能力は分からない。'
EXAMPLES[34] = 'Gửi 2 MB với quy ước 1 MB=10^6 byte qua đường 8 Mbps, hiệu suất 50%. Theo mô hình bỏ các trễ khác, mất bao lâu?~2MB（1MB=10^6バイト）を8Mbps、効率50%で送る。他の遅延を除いた時間は。~Dữ liệu = 2×10^6×8 = 16×10^6 bit.|Tốc độ hữu ích = 8×10^6×0,5 = 4×10^6 bit/s.|Thời gian = dữ liệu/tốc độ = 4 giây. MB và Mbps không được chia trực tiếp khi chưa đổi byte sang bit.~データ量は16×10^6ビット。|実効速度は4×10^6ビット毎秒。|割り算で4秒。バイトとビットをそろえる。~Hiệu suất 50% làm tốc độ hữu ích giảm, không làm dữ liệu cần gửi tự giảm một nửa.~効率で減るのは実効速度で、元データ量ではない。'
EXAMPLES[35] = '192.168.1.130/26 thuộc subnet nào? Nêu mạng, broadcast và số host theo mô hình thông thường.~192.168.1.130/26のネットワーク、ブロードキャスト、通常のホスト数を求める。~26 bit mạng còn 6 bit host; khối có 64 địa chỉ. Các ranh giới octet cuối là 0,64,128,192.|130 nằm trong 128–191: mạng là 192.168.1.128, broadcast là 192.168.1.191.|Host từ .129 đến .190, số lượng 64−2=62. Giữ nguyên ba octet đầu trong ví dụ này.~ホスト部6ビットで64個、最後の桁の区切りは0,64,128,192。|130は128〜191なのでネットワークは.128、ブロードキャストは.191。|通常のホストは.129〜.190の62個。~Không làm tròn về 192.168.1.0 chỉ vì ba octet đầu giống nhau; /26 không phải /24.~先頭三つが同じだから/24の境界に丸めない。'
EXAMPLES[36] = 'PC biết IPv4 của một dịch vụ ngoài subnet. Nó có cần MAC của máy chủ xa để tạo khung LAN đầu tiên không?~PCがサブネット外サーバのIPv4を知る。最初のLANフレームに遠方サーバのMACが必要か。~Xác định đích ngoài subnet nên chọn đường qua gateway theo bảng định tuyến của máy.|Ở chặng LAN đầu, khung gửi tới giao diện gateway; nếu cần thì tìm MAC cục bộ qua ARP.|Router nhận gói IP rồi chuyển tiếp theo chặng sau. MAC của khung phục vụ chặng hiện tại, không thay IP đích cuối.~外部宛てなのでゲートウェイへの経路を使う。|最初のリンクはゲートウェイのMAC宛てで必要ならARPを使う。|ルータはIPを基に次へ転送し、各リンクのフレームを使う。~Không dùng DNS để tìm MAC, và không gán MAC cuối Internet cho mọi khung.~DNSをMAC解決に使わず、全区間を同じフレームと考えない。'
EXAMPLES[37] = 'A gửi thư chính cho B, C nhận bản sao hiển thị, D nhận bản sao ẩn. Chọn trường rồi giải thích cái gì không được bảo vệ bởi cách ghi đó.~主宛先B、写しC、非表示の写しDに送る。宛先と保護範囲を説明する。~Ghi B vào To, C vào Cc và D vào Bcc.|B và C không thấy địa chỉ D qua danh sách Bcc của thư nhận; Cc vẫn hiển thị.|Đây là xử lý hiển thị người nhận. Mã hóa nội dung và xác minh chữ ký cần cơ chế riêng như S/MIME khi sử dụng phù hợp.~BをTo、CをCc、DをBccへ指定する。|BccのDは他の受信者へ表示しない。|本文の暗号化や署名は別の仕組みで扱う。~Bcc không đồng nghĩa mã hóa thư và không ngăn mọi cách chuyển tiếp nội dung.~Bccを本文の秘匿や転送防止と同一視しない。'

# Four teaching units per lesson: explanation VI/JA, then analogy VI/JA.
NOTES = {}
NOTES[57] = '''
Chiến lược hệ thống cần phục vụ mục tiêu kinh doanh của cả tổ chức. Một phòng mua phần mềm tốt riêng cho mình vẫn có thể gây nhập liệu lặp và khó chia sẻ với phòng khác. EA giúp nhìn liên hệ nghiệp vụ, dữ liệu, ứng dụng và công nghệ giữa hiện trạng với mục tiêu. BPR đặt lại câu hỏi cách làm căn bản; BPM duy trì quản lý và cải tiến quy trình. Đừng tự động hóa bước thừa chỉ vì nó đã tồn tại lâu.~システム戦略は全社の目標との整合で考えます。部門ごとの便利さが全体の重複を生むことがあります。EAは業務から技術までを横断し、BPRとBPMは改革と継続管理の観点で業務を見ます。~Mỗi phòng xây một cầu thang riêng rất đẹp nhưng không nối được các tầng vẫn là ngôi nhà khó dùng. Tối ưu phần cần đặt trong quan hệ với toàn nhà.~各部屋の設備が良くても建物全体でつながらなければ使いにくいのと同じです。
RPA phù hợp thao tác có quy tắc; BPO là giao nghiệp vụ cho ngoài; cloud là cách nhận tài nguyên/dịch vụ. Chúng không phải ba mức của cùng một chiếc thang. IaaS, PaaS, SaaS phân chia phần nhà cung cấp vận hành khác nhau: thuê hạ tầng khác với dùng ứng dụng hoàn chỉnh. Tổ chức vẫn cần biết mình giữ trách nhiệm gì về dữ liệu, quyền và cách sử dụng, không vì “trên cloud” mà hết quản lý.~RPA、BPO、クラウドは異なる選択です。IaaS、PaaS、SaaSでは提供する層が違い、利用側が管理する範囲も変わります。外部サービスを使ってもデータや利用権限などの責任を確認します。~Thuê mặt bằng, thuê bếp đã có thiết bị và mua suất ăn làm sẵn là các mức nhận dịch vụ khác nhau. Nhận nhiều dịch vụ hơn không có nghĩa nhu cầu người ăn được tự quyết đúng.~場所、設備付きの厨房、完成した食事では提供範囲が違い、利用目的の判断は残ります。
SOA tổ chức chức năng thành dịch vụ có giao diện để phối hợp; BI dùng dữ liệu hỗ trợ quyết định. Muốn báo cáo có ý nghĩa phải hiểu dữ liệu từ đâu, thống nhất ý nghĩa các mục và chọn câu hỏi kinh doanh. Một dashboard nhiều biểu đồ vẫn có thể không giúp quyết định nếu đo thứ không liên quan mục tiêu. Requirement definition nối nhu cầu bên liên quan với chức năng và chất lượng phải đạt trước khi xây hay mua.~SOAはサービスの組合せ、BIは意思決定へのデータ活用です。指標は業務の問いと結び付け、データの意味と出所を確認します。要件定義は目的から必要な機能と品質へつなぐ活動です。~Bảng đồng hồ xe có ích vì chỉ tốc độ, nhiên liệu và cảnh báo liên quan lái xe; thêm số trang trí không làm người lái quyết định tốt hơn.~運転に必要な情報を示す計器だから役立つのであり、数字の多さ自体が価値ではありません。
RFI thu thập thông tin khi còn tìm hiểu phương án; RFP nêu yêu cầu để xin đề xuất. Sau đó so cả lợi ích, chi phí vòng đời và rủi ro chứ không chỉ giá mua. ROI phải theo định nghĩa lợi ích được cho, TCO tính cả chi phí phát sinh trong sử dụng. Đưa privacy vào từ thiết kế giúp tránh thu thập dữ liệu không cần rồi mới tìm cách bảo vệ về sau; đây là quyết định yêu cầu, không chỉ một công cụ ở cuối.~RFIで情報を集め、RFPで要求に対する提案を求めます。投資評価には利益の定義と運用を含む費用を確認します。プライバシー保護も上流から設計へ組み込みます。~Hỏi “có những loại xe nào?” khác với gửi nhu cầu để các hãng báo phương án. Giá mua rẻ chưa chắc tổng tiền nhiên liệu, bảo trì và vận hành thấp.~車種の情報収集と要件付き提案依頼は別で、購入額だけでは維持費まで比較できません。
'''
NOTES[58] = '''
SWOT cần hai phép tách trước khi xếp ô: bên trong hay bên ngoài, thuận lợi hay bất lợi với mục tiêu. “Có kỹ sư mạnh” là năng lực nội bộ; “nhu cầu tăng” là môi trường bên ngoài. Cùng một sự kiện có thể có ý nghĩa khác với doanh nghiệp khác nên phải đọc bối cảnh. Sau phân loại còn cần nghĩ cách tận dụng và ứng phó; bốn ô không tự sinh chiến lược chỉ bằng điền đủ từ khóa.~SWOTは内外と有利不利の二軸で整理します。社内技術と市場需要は出所が違います。同じ環境変化でも立場で意味が変わるため、整理後にどう対応するかを考えます。~Sức khỏe của người đi biển là điều bên trong, thời tiết là bên ngoài. Thuyền chắc không làm thời tiết biến thành nguồn lực nội bộ.~船の状態と天候では、自分側の条件と外部条件が違います。
PPM đặt các mảng kinh doanh theo tăng trưởng thị trường và thị phần tương đối. Thị trường tăng nhanh thường cần nguồn lực để theo kịp; vị thế cao có thể giúp tạo dòng tiền. Vì vậy phải nhìn cả hai trục để phân biệt star, cash cow, question mark và dog. Tên gọi là công cụ phân tích danh mục, không phải mệnh lệnh cứ thấy “dog” là lập tức bán mà bỏ mọi thông tin khác.~PPMは市場成長率と相対的シェアを合わせて資源配分を考える道具です。二つの軸の高低で四つに分けますが、分類名だけで全判断を自動化するものではありません。~Vườn cây có cây đang lớn cần chăm và cây trưởng thành đang cho quả. Phân bổ nước cần nhìn cả nhu cầu lẫn khả năng tạo thu hoạch, không chỉ nhìn chiều cao.~成長中の木と収穫期の木では必要な手入れが違うように、事業を組み合わせて見ます。
BSC nối chiến lược với bốn góc nhìn: tài chính, khách hàng, quy trình nội bộ, học tập và phát triển. CSF là điều then chốt cần thành công; KPI là thước đo để theo dõi điều đó. “Giao đúng hẹn quan trọng” khác với “tỷ lệ giao đúng hẹn tháng này là 92%”. Chỉ số dễ đo nhưng lệch mục tiêu có thể khuyến khích hành vi sai, nên phải hiểu vì sao theo dõi con số đó.~BSCは四つの視点で戦略を評価します。CSFは重要な成功要因、KPIはその状況を測る指標です。測りやすさだけで選ばず、目的との関係を確認します。~Muốn cơ thể khỏe không chỉ nhìn cân nặng: còn vận động, sức bền và thói quen. Một con số có thể đẹp lên trong khi mục tiêu thật xấu đi.~健康を一つの数値だけで判断しないのと同じです。
Value chain tìm hoạt động tạo giá trị, core competence tìm năng lực cốt lõi khó bắt chước; benchmarking học từ thực hành tốt. Marketing 4P là các lựa chọn sản phẩm, giá, kênh và xúc tiến kết hợp nhau. Quy mô lớn và kinh nghiệm tích lũy có thể tạo hiệu quả chi phí theo điều kiện, nhưng không nên suy ra mọi tăng trưởng đều tốt. Hãy nối công cụ với câu hỏi: cần đánh giá môi trường, danh mục, hoạt động hay mục tiêu?~価値連鎖、核となる能力、優良事例との比較、4Pでは調べる対象が違います。規模や経験の効果も条件の下で考えます。道具の名称より、答えたい経営の問いと対応付けます。~Bản đồ thời tiết, lịch chăm cây và bảng thu hoạch đều giúp làm vườn nhưng không thể dùng một tờ thay cho tất cả. Công cụ quản trị cũng có câu hỏi riêng.~庭の天候、作業、収穫の資料を目的別に使うように、分析手法も使い分けます。
'''
NOTES[59] = '''
POS ghi nhận bán hàng tại thanh toán; ID-POS nối giao dịch với định danh khách để phân tích hành vi theo người. Dữ liệu có ích tùy câu hỏi: tổng bán theo giờ khác với cùng khách mua lại gì. MRP đi từ kế hoạch sản phẩm, cấu thành và tồn kho để suy nhu cầu vật tư; JIT tổ chức cung ứng đúng thứ, lượng và lúc cần. Không phải cứ giảm tồn kho bất kể điều kiện là đã vận hành tốt.~POSと顧客を対応させたID-POSでは分析できる問いが違います。MRPは計画と構成と在庫から必要資材を求め、JITは必要時の供給を考えます。在庫を減らす数字だけが目的ではありません。~Biết cả lớp ăn bao nhiêu suất khác với biết từng bạn có quay lại ăn món gì. Tính nguyên liệu cần nấu cũng khác điều phối khi nào giao nguyên liệu.~総数の記録、個人との対応、材料量、供給時期は別の問いです。
EC nói về thương mại qua mạng; BtoB, BtoC và CtoC phân loại theo các bên tham gia. EDI tập trung trao đổi dữ liệu giao dịch có cấu trúc và quy tắc thống nhất giữa hệ thống; một email viết tự do không tự là EDI chỉ vì được gửi điện tử. Đọc đề cần xem ai giao dịch và dữ liệu có được hệ thống xử lý theo định dạng chung hay phải con người đọc lại.~ECの分類は取引相手、EDIは取引データの共通形式による交換に着目します。電子メールで送るだけでは同じ意味になりません。主体と情報の扱いを分けて確認します。~Hai công ty gửi nhau biểu mẫu chuẩn để máy tự nhận khác với nhắn “mai giao như cũ nhé” rồi một người nhập lại. Cùng dùng mạng nhưng mức chuẩn hóa khác nhau.~共通様式で自動処理する伝票と、自由文を読んで転記する連絡では形式の共有が違います。
RFID dùng sóng vô tuyến để đọc thông tin thẻ; embedded system điều khiển chức năng trong thiết bị; IoT nối vật với mạng để thu thập và tác động. Sensor đưa đại lượng vật lý vào dạng thông tin, actuator biến lệnh thành tác động vật lý. Một chuỗi điều khiển phải có cả hướng đo và hướng tác động nếu tình huống yêu cầu, chứ không phải gắn cảm biến là tự sửa được mọi trạng thái.~RFID、組込み、IoTの役割を区別します。センサは測定して情報へ、アクチュエータは制御情報から動作へ変換します。測ることだけで物理状態を変えられるわけではありません。~Nhiệt kế cho biết nóng, còn van hay quạt mới thay đổi môi trường. Người chỉ báo và bộ phận hành động là hai phía của vòng điều khiển.~温度計は状態を知り、弁やファンは状態へ働き掛けます。
Edge computing đưa xử lý gần nơi sinh dữ liệu để phù hợp nhu cầu như phản hồi tại chỗ; cloud vẫn có thể tổng hợp nhiều nguồn. IoT tạo dữ liệu, machine learning có thể dùng dữ liệu đó để dự đoán, nhưng dự đoán cần đánh giá và không tự là sự thật. Smart grid phối hợp điện và thông tin; HEMS tập trung năng lượng trong nhà. Các tên hệ thống cần gắn với đối tượng và phạm vi, không học như một danh sách viết tắt.~現場処理と中央の集約は組み合わせられます。IoTの測定データとAIの予測は区別し、予測の性能を確認します。電力網全体と家庭内管理のように対象範囲を合わせて理解します。~Người trực tại chỗ xử lý ngay một cảnh báo, trung tâm nhìn xu hướng nhiều nơi. Hai cấp có thể phối hợp, không nhất thiết phải chọn bỏ hẳn một cấp.~現場の即時判断と本部の全体分析は役割を分担できます。
'''
NOTES[60] = '''
Cơ cấu tổ chức ảnh hưởng cách phối hợp: theo chức năng tập trung chuyên môn, ma trận kết hợp hai trục như chức năng và dự án. Đổi sơ đồ không tự xóa mọi xung đột trách nhiệm, vì nhân viên có thể phải cân bằng yêu cầu từ hai phía. OJT học trong công việc thực tế; Off-JT tách khỏi tác nghiệp thường ngày. Chọn cách học theo năng lực cần rèn, không kết luận một loại luôn tốt hơn.~職能とマトリックスでは調整の仕方が異なります。二軸を持つ構造には責任や優先順位の整理も必要です。OJTとOff-JTは学ぶ場所と方法の違いで、目的に合わせて使います。~Một cầu thủ vừa thuộc nhóm luyện chuyên môn vừa tham gia đội thi đấu cần biết ai quyết định điều gì. Có hai sơ đồ không tự tạo hai lần thời gian.~専門練習と試合チームの両方に属す人には、役割と優先の調整が必要です。
Chọn công cụ phân tích theo câu hỏi: Pareto xem nhóm nguyên nhân đóng góp lớn, scatter xem quan hệ hai biến, fishbone sắp giả thuyết nguyên nhân. Tương quan không tự chứng minh nhân quả. Linear programming cần hàm mục tiêu và các ràng buộc, không chỉ chọn sản phẩm có lợi nhuận đơn vị cao nhất. Phương án lời nhiều nhưng thiếu nguyên liệu là không khả thi và phải loại trước khi so giá trị tối ưu.~項目の寄与、二量の関係、原因候補では使う図が違います。線形計画では目的と制約をそろえ、実行不可能な案を利益が高いという理由で採用しません。相関と因果も区別します。~Mua món rẻ nhất theo đơn vị chưa chắc đủ bữa trong ngân sách và thời gian nấu. Bài toán tối ưu phải tôn trọng mọi giới hạn cùng lúc.~一つの単価だけでなく予算や時間などの制約を同時に満たす必要があります。
Tách fixed cost khỏi variable cost để thấy bán thêm một đơn vị đóng góp bao nhiêu. Unit contribution là giá bán trừ biến phí đơn vị; phần đóng góp tổng trước hết bù định phí, vượt qua mới là lợi nhuận trong mô hình. Điểm hòa vốn không phải doanh thu bằng biến phí, mà doanh thu bằng toàn bộ chi phí. Expected value lại là bình quân theo xác suất, không phải cam kết lần kinh doanh tới đúng bằng con số trung bình.~単位限界利益で固定費を回収し、超えた分が利益になります。損益分岐では総費用を回収します。期待値は確率で重み付けした平均で、一回の結果の保証ではありません。~Mỗi vé bán thêm sau chi phí phục vụ còn góp một ít trả tiền thuê rạp. Khi tiền thuê chưa được bù thì đông khách hơn chưa nhất thiết đã có lãi.~追加の一枚の貢献が会場費の回収に使われ、回収後に利益になります。
Balance sheet là ảnh tại một thời điểm; income statement đo kết quả trong một kỳ; cash-flow statement theo dõi tiền vào ra. Có lợi nhuận không đồng nghĩa có đủ tiền trả ngay, vì thu chi và ghi nhận có thể lệch thời điểm. Depreciation phân bổ giá trị tài sản dùng nhiều kỳ, không phải mỗi năm chi thêm đúng số tiền khấu hao đó. Trong bài tính phải dùng giá trị còn lại, thời gian và phương pháp được đề cho, không suy thành luật thuế chung.~貸借対照表は時点、損益は期間の成績、キャッシュフローは現金の動きです。利益と手元資金は一致しません。減価償却は費用配分であり同額の現金支出が毎年生じるとは限りません。~Ảnh ví tiền hôm nay, bảng thu nhập tháng và lịch tiền thực về là ba tài liệu khác nhau. Máy mua năm trước có thể được phân bổ chi phí năm nay mà không mua lại.~今の財布、期間の成績、現金の入出金は別の見方です。
'''
NOTES[61] = '''
Trong quyền tác giả cần phân biệt ý tưởng với biểu đạt sáng tạo cụ thể. Hiểu cùng thuật toán không có nghĩa được sao chép mã của người khác; ngược lại không thể kết luận mọi cách thực hiện một ý tưởng đều thuộc độc quyền của người đã viết đầu tiên chỉ dựa quyền tác giả. Patent, utility model, design và trademark bảo vệ các đối tượng khác nhau theo điều kiện luật. Hãy bắt đầu bằng “đang bảo vệ thứ gì?” trước khi chọn tên quyền.~アイデアと創作的な表現を区別します。同じ算法を使うことと他人のコードを複製することは別です。発明、考案、デザイン、識別標識など、保護の対象から権利を整理します。~Cùng ý tưởng kể một câu chuyện không đồng nghĩa cùng những câu văn; tên thương hiệu trên bìa cũng là một đối tượng khác. Ví von chỉ giúp phân loại, không quyết định kết luận pháp lý của một vụ cụ thể.~話の発想、具体的な文章、表紙のブランド名は対象が違います。例えだけで個別の法的判断をしません。
Trade secret cần cả ba yếu tố: hữu ích cho hoạt động, được quản lý như bí mật và không công khai. Chỉ gọi một tài liệu là “bí mật” nhưng ai cũng truy cập công khai không tự đạt các điều kiện. Đối chiếu tình huống với từng yếu tố thay vì thấy từ “know-how” là chọn ngay. Có cơ chế quyền khác không có nghĩa mọi thông tin đều cần đăng ký cùng một cách; mỗi cơ chế có nền tảng riêng.~営業秘密は有用性、秘密管理性、非公知性を合わせて確認します。秘密と呼ぶだけでは足りません。ノウハウという名称で即断せず、管理と公開状況を具体的に見ます。~Công thức món ăn được giữ trong khu vực hạn chế khác với công thức đã dán công khai trước cửa. Cùng một nội dung nhưng cách quản lý và công khai ảnh hưởng điều kiện.~同じ製法でも管理方法と公知かどうかを分けて考えます。
Thông tin cá nhân không chỉ là một danh sách có họ tên in sẵn. Cần xét thông tin về cá nhân còn sống có nhận biết người cụ thể hay dễ đối chiếu với thông tin khác không; dữ liệu trong cơ sở được tổ chức để tìm kiếm còn liên quan khái niệm personal data theo nguồn chính thức. Đổi tên thành mã không tự chứng minh đã mất khả năng nhận biết nếu bên giữ dễ nối mã lại với người. Nội dung bài là phân biệt khái niệm, không suy một biện pháp kỹ thuật thành tuân thủ pháp luật đầy đủ.~氏名の有無だけでなく、生存する個人の識別と容易な照合を考えます。コードへ置き換えても対応表で容易に識別できる場合は、それだけで個人性を否定しません。技術的な置換だけを全面的な適法性と同一視しません。~Cất tên trong sổ A và mã trong sổ B chưa làm người quản lý cả hai sổ quên mất ai là ai. Khả năng nối thông tin mới là điều cần xét.~二冊に分けても管理者が簡単に対応させられるなら、識別の可能性は残ります。
Hợp đồng phân công quan hệ lao động và trách nhiệm: tuyển trực tiếp, phái cử và nhận khoán không giống nhau về bên tuyển, bên chỉ đạo và đối tượng cam kết. Trong mô hình nhận khoán của tài liệu, bên nhận tổ chức thực hiện để hoàn thành công việc; không đơn giản biến người của bên nhận thành nhân viên được chỉ đạo trực tiếp bởi bên đặt. Ngoài ra phải đọc license khi dùng phần mềm: tải miễn phí không tự xóa điều kiện sử dụng hay nghĩa vụ giữ bí mật.~雇用、派遣、請負では雇用者、指揮命令、契約の目的が違います。請負側が作業を管理する関係と、派遣先が指示する関係を混同しません。ソフトも無料かどうかだけでなく利用条件を確認します。~Đặt một tiệm làm chiếc bánh theo yêu cầu khác với thuê thợ đến rồi trực tiếp điều phối công việc của họ. Tương tự không có nghĩa mọi trường hợp pháp lý đều giống việc đặt bánh.~完成品の注文と人の作業指示を分けるための例で、個別契約の結論を決めるものではありません。
'''
NOTES[21] = '''
Nếu RAM là tài nguyên hữu hạn mà nhiều chương trình đều cần dùng, OS phải quyết định phần nào được giữ ở đó. Cấp vùng cố định dễ quản lý nhưng có thể để trống bên trong; vùng biến đổi linh hoạt hơn nhưng tạo các khoảng trống rải rác. Virtual memory tách không gian địa chỉ chương trình nhìn thấy khỏi cách dữ liệu đang nằm trong RAM. Nhờ đó không phải mọi phần của chương trình đều phải hiện diện đồng thời.~限られた主記憶を複数のプログラムで使うため、OSが割当てを管理します。固定区画と可変区画では空き領域の生じ方が違います。仮想記憶は見えるアドレス空間と物理的な配置を分けます。~RAM như mặt bàn, ổ lưu trữ như tủ tài liệu. Không cần bê toàn bộ tủ lên bàn, nhưng muốn làm với trang nào thì phải đưa đúng phần cần dùng lên trước.~作業机と書庫の例では、すべてを同時に机へ置かず、必要な資料を取り出します。
Paging chia không gian ảo thành page và RAM thành frame cùng kích thước trong mô hình cơ bản. Page table cho biết page đang tương ứng frame nào và trạng thái hiện diện. Địa chỉ gồm số page và offset trong page: khi đổi sang vật lý, tra để thay số page bằng frame nhưng giữ offset. Nhớ được quy tắc “phần nào đổi, phần nào giữ” quan trọng hơn chỉ thuộc từ bảng trang.~ページとフレームの大きさをそろえ、ページ表で対応を調べます。アドレスのページ番号をフレーム番号へ変え、ページ内変位はそのまま使います。変換する部分と残す部分を区別します。~Các tờ hồ sơ đánh số trang có thể nằm ở các ngăn khác nhau. Danh mục chỉ ngăn, còn vị trí chữ trên đúng tờ vẫn như cũ. Danh mục không phải nơi chứa nội dung trang.~目録で紙の置場を探しても、その紙の中の位置は変わらないという例です。
Page fault xảy ra khi cần page chưa hiện diện theo tình huống đang xét; OS phải xử lý nạp trang rồi mới tiếp tục lệnh phù hợp. Nếu còn frame trống có thể dùng nó; nếu hết chỗ cần chọn page để thay. Page-in đưa page vào RAM; page-out ghi page ra theo nhu cầu của cơ chế, đặc biệt khi thay đổi cần giữ. Vì vậy không phải mọi fault đều đồng nghĩa phải ghi ra một page chưa thay đổi.~必要なページが主記憶にないとページフォールトの処理が必要です。空きがあれば利用し、なければ置換を選びます。読み込みと書き出しを区別し、フォールトが常に同じ書出しを伴うとは考えません。~Bàn còn trống thì lấy thêm tờ lên; bàn hết chỗ mới cần cất bớt. Một tờ đã sửa cần bảo toàn thay đổi trước khi bỏ bản đang làm.~机の空きの有無と、資料に変更があるかで必要な動作が変わります。
FIFO dựa thời điểm vào, LRU dựa lần dùng gần nhất, LFU dựa số lần dùng theo quy tắc thống kê của đề. Một hit không làm trang “vào lại” trong FIFO nhưng cập nhật độ gần trong LRU. Khi mô phỏng, ghi khung sau từng lần tham chiếu và chỉ tăng fault khi page vắng. Nếu liên tục thay trang tới mức phần lớn thời gian dùng cho đổi trang, đó là thrashing; bộ nhớ ảo không có nghĩa RAM chậm nhanh đều như nhau.~FIFO、LRU、LFUは選ぶ根拠が違います。ヒット時に更新する情報も異なるので、各参照後の状態を記録します。ページの出入れが多すぎるとスラッシングで実行が進みにくくなります。~Người quản lý bàn có thể cất tờ lấy lên lâu nhất, tờ lâu chưa đọc hoặc tờ ít đọc nhất. Đổi quy tắc là đổi lịch sử cần theo dõi.~いつ机に置いたか、最後に読んだのはいつか、何回読んだかは別の記録です。
'''
NOTES[22] = '''
Để phân biệt thiết bị nhập và xuất, chọn điểm nhìn từ máy tính: dữ liệu đi vào hay kết quả đi ra. Một màn hình cảm ứng chứa cả phần hiển thị và phần nhận chạm nên có hai vai trò. Scanner tạo dữ liệu ảnh; OCR thêm bước nhận dạng chữ từ ảnh; OMR nhận vị trí tô dấu theo mẫu. Ảnh chụp trang sách chưa tự là văn bản có thể sửa: phải xét bước chuyển từ hình ảnh sang ký tự.~入力か出力かはコンピュータから見た向きで考えます。画像を取り込むこと、文字として認識すること、マークを読むことは別です。タッチパネルのように複数の役割を持つ製品もあります。~Mắt nhìn trang giấy giống bước lấy hình; đọc ra chữ là thêm bước diễn giải. Chụp được ảnh một bài chưa chứng minh máy đã hiểu đúng từng chữ.~紙を撮影することと文字を読むことは違います。画像があるだけでは文字認識の正しさは分かりません。
Màn hình hiển thị một lưới điểm nhưng độ chi tiết còn phải đọc theo số pixel và kích thước. dpi là mật độ theo chiều dài, không phải tốc độ. VRAM giữ dữ liệu phục vụ hiển thị, không thay vai trò toàn bộ bộ nhớ chương trình. Khi bài cho chiều rộng theo inch và dpi, trước hết đổi mỗi chiều thành số điểm rồi mới nhân để ra tổng số điểm; tránh nhân một thông số mật độ rồi gọi đó là diện tích.~画素数、物理サイズ、DPIを分けます。DPIは長さ当たりの密度なので、各辺を画素数に直してから総画素数を求めます。VRAMは表示のための記憶で、主記憶全体と同じ役割ではありません。~Lát nền phải biết mỗi hàng có bao nhiêu viên và có bao nhiêu hàng. “10 viên trên một mét” chưa cho biết cả căn phòng có bao nhiêu viên.~一辺のタイル密度だけでは部屋全体の枚数は求まりません。
Máy in chọn theo cơ chế tạo dấu: dot impact dùng tác động cơ học qua ribbon nên phù hợp giấy nhiều liên; các phương thức không va đập tạo hình bằng cơ chế khác. Các thông số tốc độ và độ phân giải trả lời câu hỏi khác nhau. Một máy in nhanh chưa chắc tạo chi tiết mịn hơn. Cần lấy yêu cầu như giấy nhiều liên, cách tạo dấu hay đơn vị ppm/dpi để chọn, không theo tên thương mại.~印字の仕組み、速度、解像度を別々に確認します。複写用紙への打撃と、他の印字方式は特性が違います。速さの指標を細かさの指標と混同しません。~Đóng dấu mạnh để in qua nhiều lớp giấy khác với vẽ mực lên lớp trên cùng. Còn làm nhanh và làm nét là hai tiêu chí riêng.~複数枚へ打撃を伝えること、表面へ描くこと、速度、細かさを分けて考えます。
Giao tiếp thiết bị gồm cả cách truyền, hình thức nối và phần mềm điều khiển. Serial/parallel nói cách truyền bit trong mô hình; star/daisy chain nói cấu trúc nối; driver giúp phần mềm làm việc với thiết bị; hot plug nói điều kiện cắm/rút khi có điện, còn plug-and-play nói nhận biết/cấu hình. Thấy đầu cắm giống nhau chưa đủ kết luận cùng tốc độ hay hỗ trợ mọi tính năng.~ビットの送り方、接続の形、制御ソフト、通電中の抜差し、自動設定は別の観点です。端子の形だけで転送速度や対応機能をすべて判断しません。~Dây đường, sơ đồ đường, người điều phối và quy tắc mở cổng là các lớp khác nhau của một hệ thống vận chuyển. Một cái đầu cắm không mô tả hết các lớp đó.~道、接続図、制御役、接続時の条件は別の情報です。
'''
NOTES[47] = '''
Phát triển hệ thống không bắt đầu bằng chọn ngôn ngữ lập trình. Trước hết cần hiểu mục tiêu kinh doanh, người sử dụng và vấn đề phải giải quyết; sau đó mới biến nhu cầu thành yêu cầu kiểm tra được. “Tra cứu nhanh” còn mơ hồ, còn quy định thời gian phản hồi trong điều kiện tải xác định thì có cơ sở đánh giá. Chức năng nói hệ thống làm gì; phi chức năng nói các chất lượng và ràng buộc phải đạt khi làm điều đó.~まず業務の目的と利用者を理解し、検証できる要求へ具体化します。「速い」だけでは条件が曖昧です。機能は何をするか、非機能は性能や信頼性など、どういう水準や制約で提供するかを扱います。~Xây nhà phải biết ai ở và cần những phòng nào trước khi mua gạch. Số phòng và mức cách âm đều là yêu cầu, nhưng thuộc hai mặt khác nhau.~家の用途と必要な部屋を決めてから材料を選ぶように、目的と要求が実装より先です。
Thiết kế đi từ tổng thể tới chi tiết: phân chia chức năng cho phần cứng/phần mềm, xác định yêu cầu phần mềm, chia thành thành phần rồi thiết kế xử lý bên trong. Một màn hình đẹp chưa giải quyết việc các module phối hợp hoặc dữ liệu được lưu ra sao. External design nhìn từ phía người dùng, internal design nhìn cách hiện thực. Hai góc nhìn cần ăn khớp để đặc tả bên ngoài thực sự có thể xây dựng.~全体構成からソフトの要求、構成要素、内部処理へと具体化します。利用者に見える外部設計と、実現方法を扱う内部設計が対応している必要があります。画面だけで全設計が終わるわけではありません。~Bản phối cảnh cho người ở xem khác bản kỹ thuật cho đội xây. Hai bản mô tả cùng ngôi nhà nên không được mâu thuẫn.~完成イメージと施工図は用途が違っても、同じ建物を実現するため整合している必要があります。
Các mức test trả lời các câu hỏi khác nhau. Unit test kiểm tra một đơn vị, integration test xét kết nối giữa đơn vị, system test đối chiếu hệ thống tích hợp với yêu cầu. Đơn vị nào cũng chạy đúng riêng chưa chứng minh chúng dùng cùng định dạng dữ liệu hay phối hợp đúng. Khi chọn mức test trong đề, tìm đối tượng và căn cứ đối chiếu; đừng chỉ dựa vào tên người đang thực hiện test.~単体では個々の処理、結合では接続、システムでは全体と要求の対応を確認します。単独で正しい部品でも連携に問題があり得ます。対象と確認する仕様からテストの種類を判断します。~Từng nhạc cụ không hỏng chưa đủ để dàn nhạc chơi đúng nhịp. Kiểm tra từng người và kiểm tra hòa tấu có mục tiêu khác nhau.~一人ずつ演奏できても合奏が合うとは限りません。個別確認と連携確認を分けます。
Acceptance test giúp bên nhận đánh giá điều kiện chấp nhận; operational test xem thủ tục và điều kiện chạy thực tế. Sau bàn giao còn bảo trì: sửa lỗi, thích ứng và thay đổi theo nhu cầu. Review có thể tìm mâu thuẫn ngay trên yêu cầu hoặc thiết kế trước khi có mã chạy. Vì vậy chất lượng không phải việc riêng của “giai đoạn test cuối”, mà cần theo dõi liên hệ giữa yêu cầu, thiết kế, hiện thực và kiểm tra.~受入れは合意した条件、運用テストは実際の運用を確認します。稼働後にも修正と変更が続きます。要求や設計のレビューも早期の品質確保で、最後の実行テストだけに任せません。~Kiểm tra bản vẽ trước khi xây thường giúp tránh phải đục tường sau này. Nhưng bản vẽ được duyệt cũng không thay thế kiểm tra căn nhà đã xây.~図面の点検と完成物の検査は両方に意味があります。
'''
NOTES[48] = '''
Mô hình phát triển quyết định cách chia và kiểm tra công việc qua thời gian. Waterfall tổ chức các công đoạn theo trình tự; prototype giúp làm rõ điều chưa biết bằng mẫu thử; spiral gắn vòng phát triển với đánh giá rủi ro. Không có tên mô hình tự bảo đảm dự án thành công. Hãy nhìn độ rõ của yêu cầu, chi phí thay đổi và loại phản hồi cần nhận để hiểu vì sao một cách tổ chức phù hợp với tình huống.~工程を順に進める方法、試作品で要求を確かめる方法、リスク評価を繰り返す方法では、未知の部分への向き合い方が違います。名称だけで優劣を決めず、要求の確かさと必要な確認を考えます。~Chốt bản vẽ rồi xây khác với làm mô hình căn bếp để người dùng thử trước. Mẫu thử dùng để học, không tự là sản phẩm đã sẵn sàng bàn giao.~図面の確定と、使い勝手を試す模型は目的が違います。試作品がそのまま完成品とは限りません。
Agile dùng các vòng ngắn để tạo phần hoạt động, nhận phản hồi và điều chỉnh. Điều này không có nghĩa bỏ kế hoạch, tài liệu hay chất lượng. Scrum tổ chức nhịp công việc: ưu tiên ở backlog, mục tiêu của sprint, phối hợp hằng ngày và xem xét tăng trưởng sản phẩm. Khi yêu cầu đổi, nhóm vẫn cần hiểu mục tiêu và giới hạn công việc, không phải thêm bất cứ thứ gì ngay giữa mọi thao tác.~アジャイルは短い反復で動くものを確かめ適応する考えです。計画や品質を捨てる意味ではありません。スクラムではバックログ、スプリントの目標、日々の調整などで仕事を整理します。~Viết từng chương rồi nhận phản hồi giúp chỉnh cuốn sách sớm; không có nghĩa mọi người tự viết bất kỳ chương nào mà không thống nhất mạch chuyện.~章ごとに読んでもらい改善しても、本全体の方向を合わせる必要はあります。
Review và retrospective không phải hai tên của cùng một buổi họp. Review nhìn sản phẩm và hướng điều chỉnh với các bên liên quan; retrospective nhìn cách nhóm làm việc để cải tiến. Daily Scrum là điểm phối hợp ngắn về tiến triển hướng mục tiêu, không chỉ đọc báo cáo cho cấp trên. Phân biệt đối tượng được kiểm tra sẽ giúp nhớ đúng sự kiện hơn là học thuộc thời lượng đơn lẻ.~レビューは成果と今後の方向、レトロスペクティブは働き方の改善を扱います。日次の確認は目標に向けた進め方の調整です。何を検査・改善するイベントかで整理します。~Khách nếm món mới là phản hồi về món; đầu bếp bàn việc phối hợp trong bếp là cải tiến cách làm. Cùng xảy ra sau một ca nhưng phục vụ hai việc.~客の試食と、厨房での働き方の振返りは対象が違います。
Các thực hành kỹ thuật giúp vòng ngắn vẫn kiểm soát chất lượng: test trước làm rõ hành vi mong muốn, pair programming tạo trao đổi và kiểm tra liên tục, refactoring cải thiện cấu trúc nhưng giữ hành vi quan sát được. Reverse engineering đi từ sản phẩm đang có để hiểu cấu trúc; reengineering dùng hiểu biết đó trong tái xây dựng. Configuration management giữ đúng phiên bản mã, tài liệu và cấu hình cùng nhau, tránh kiểm thử một bản nhưng bàn giao bản khác.~テスト、ペア作業、リファクタリングは反復を支える技術です。解析による理解と再構築は区別し、構成管理でコードと関連文書の版をそろえます。動作を変える改修をすべてリファクタリングとは呼びません。~Dọn lại ngăn bếp để nấu cùng món dễ hơn giống refactoring; đổi công thức món ăn là đổi hành vi. Hai việc có thể đi cùng nhưng phải nhận biết phần nào đang thay đổi.~同じ料理を作りやすく整理することと、料理そのものを変えることは別です。
'''
NOTES[49] = '''
DFD hỏi dữ liệu đi đâu và được biến đổi thế nào. External entity ở ngoài ranh giới, process biến đầu vào thành đầu ra, data store giữ dữ liệu, data flow nối các phần bằng thông tin. Mũi tên không đơn giản là “làm bước này trước bước kia”: cần đặt tên dữ liệu đang chuyển. Muốn mô tả lựa chọn và thứ tự thực hiện công việc có thể cần loại sơ đồ khác, không ép mọi ý nghĩa vào DFD.~DFDはデータの移動と変換を表します。外部、処理、蓄積、流れの四要素を区別し、矢印には移動するデータを考えます。単なる実行順序を表す矢印とは異なります。~Nhìn nguyên liệu vào bếp, món đi ra và kho chứa giúp hình dung luồng dữ liệu; còn lịch ca làm của đầu bếp là một góc nhìn khác.~食材の入出庫と調理での変化はデータの流れ、作業の時刻表とは別の見方です。
Bắt đầu bằng context diagram để chốt hệ thống gồm gì và giao tiếp bên ngoài ra sao, rồi phân rã xử lý lớn thành phần nhỏ. Chi tiết hơn phải tiếp tục giải thích được trao đổi với bên ngoài, không tự làm xuất hiện dữ liệu không nguồn gốc. Process-centered bắt đầu từ công việc; data-centered chú ý các đối tượng dữ liệu ổn định. Hai cách là điểm xuất phát để phân tích, không có nghĩa phần còn lại bị bỏ qua.~対象の境界と外部との授受を全体図で決め、処理を詳細化します。細分化してもデータの出所と行き先が説明できる必要があります。処理中心とデータ中心は着眼点の違いです。~Bản đồ toàn trường rồi phóng vào từng tòa nhà phải còn khớp cổng vào và đường nối. Phóng to không được tự đổi ranh giới thành một ngôi trường khác.~全体図から校舎へ拡大しても入口や接続が対応している必要があります。
E-R và class diagram đều có đối tượng và quan hệ nhưng phục vụ phạm vi khác. E-R tập trung mô hình dữ liệu và ràng buộc; class diagram mô tả lớp với thuộc tính, thao tác và quan hệ. Use case lại nói chức năng từ góc vai trò bên ngoài. Nếu câu hỏi cần biết khách hàng có thể làm gì, sơ đồ các bảng dữ liệu không tự trả lời đủ, dù trong đó có bảng Customer.~E-R、クラス図、ユースケース図は対象が似て見えても、データ構造、ソフトの構造、利用者と機能という焦点が違います。「顧客」という箱があるだけで利用可能な機能まで表せるわけではありません。~Danh sách tên người, sơ đồ tổ chức và danh sách việc từng vai trò được làm có thể cùng nhắc tới nhân viên nhưng không thay thế nhau.~名簿、組織図、役割別の作業一覧は同じ人でも異なる情報を示します。
Sequence cho thấy thông điệp theo thời gian giữa các bên; activity cho thấy luồng hoạt động; state machine tập trung trạng thái của một đối tượng. Với một đơn hàng, “UI gọi thanh toán rồi ghi đơn” là tương tác; “duyệt hoặc từ chối” là luồng; “chờ thanh toán → đã trả → đã giao” là trạng thái. Đổi góc nhìn giúp trả lời câu hỏi thay vì làm sơ đồ chỉ vì nó trông trực quan.~メッセージの順、活動の流れ、一対象の状態遷移を区別します。同じ注文でもどの問いに答えるかで適した図が変わります。視覚化は見た目ではなく、関係を説明するために使います。~Ảnh đường đi của đoàn xe, lịch liên lạc giữa tài xế và trạng thái của một chiếc xe đều hữu ích, nhưng mỗi hình theo dõi một thứ khác nhau.~経路、運転手間の連絡、車両の状態では、追う対象が違います。
'''
NOTES[50] = '''
Chia module nhằm có trách nhiệm rõ và giảm ảnh hưởng lan khi thay đổi. Cohesion nhìn bên trong: các việc có cùng mục đích không? Coupling nhìn giữa các module: phụ thuộc nhau mạnh tới đâu? Gom mọi chức năng vào một module không tránh được phức tạp, còn tách quá nhỏ nhưng phải đụng dữ liệu nội bộ nhau cũng không tạo độc lập. Mục tiêu thông thường là nội bộ gắn kết, giao tiếp bên ngoài rõ và ít phụ thuộc.~凝集度は内部のまとまり、結合度は外部への依存です。責務をそろえた内部と、明確で弱い外部依存を目指します。分割数だけでは設計の良さは決まりません。~Một đội bếp chia người phụ trách món rõ ràng nhưng giao nhận qua quy ước chung phối hợp dễ hơn việc ai cũng thò tay sửa nồi của người khác.~担当料理をまとめ、決めた受渡しで協力する方が、他人の鍋を直接変えるより影響を抑えられます。
Các kiểu kết hợp tăng mức phụ thuộc theo cách trao đổi: truyền dữ liệu cần thiết, truyền cả cấu trúc dư, truyền cờ điều khiển, dùng chung dữ liệu hay chạm trực tiếp nội dung bên trong. Ví dụ tính tiền chỉ cần price và quantity; truyền cả hồ sơ khách làm module biết thêm thứ không cần. Khi đọc đề, vẽ mũi tên “đang truyền gì?” và “ai quyết định việc bên trong?” để phân loại, không chỉ nhìn tên hàm.~必要な値、構造体、制御フラグ、共通データ、内部への直接干渉では依存が違います。何を渡し、誰が内部処理を指示するかを確認すると分類できます。~Đặt một món bằng tên và số lượng ít phụ thuộc hơn việc khách vào bếp tự chỉnh nhiệt và đổi nguyên liệu. Giao diện càng lộ nội bộ, thay đổi càng dễ ảnh hưởng bên ngoài.~注文内容だけ渡す場合と調理の内部へ直接介入する場合では、依存が違います。
Black-box lấy đặc tả làm căn cứ, dùng các lớp tương đương và biên để chọn dữ liệu; white-box lấy cấu trúc xử lý làm căn cứ, xét lệnh, nhánh và điều kiện. Không có một chỉ số coverage tự chứng minh không còn lỗi. Đạt statement coverage chưa chắc chạy đủ kết quả của mọi if; cho từng điều kiện đơn nhận T/F chưa chắc cho cả quyết định nhận T/F. Hãy tính kết quả trên từng ca thay vì suy từ tên độ bao phủ.~仕様から入力を選ぶ方法と、内部構造から経路を選ぶ方法を分けます。命令、分岐、条件の網羅は同じ基準ではなく、一つを満たしても無欠陥を証明するものではありません。各ケースの結果を実際に計算します。~Đi qua mọi căn phòng chưa chắc đã thử mọi cánh cửa. Số phòng đã vào và số nhánh đã đi đo hai thứ khác nhau.~すべての部屋を訪れることと、すべての扉を通ることは違います。
Top-down cần phần dưới thay tạm bằng stub; bottom-up cần driver gọi phần dưới khi phần trên chưa sẵn sàng. Phân biệt ai **gọi** ai giúp nhớ đúng hai tên. Sau thay đổi còn regression test để kiểm tra tính năng vốn đúng có bị ảnh hưởng không. Một test sửa lỗi vừa chạy xanh chỉ chứng minh tình huống đó; các giao tiếp và hành vi liên quan vẫn cần kiểm tra phù hợp.~上位からのテストでは呼ばれる下位の代わりがスタブ、下位を先に試す際に呼び出す上位の代わりがドライバです。変更後には既存機能への影響を回帰テストで確認します。~Thử loa bằng máy phát tín hiệu là có thứ gọi vào nó; thử bộ điều khiển với loa giả là thay thứ được gọi. Nhìn chiều mũi tên dễ hơn học thuộc âm của hai từ.~入力を与える側の代用品と、呼ばれて結果を返す側の代用品を区別します。
'''
NOTES[52] = '''
Dự án có thời hạn và kết quả riêng biệt, khác công việc vận hành lặp đều. Người quản lý phải phối hợp phạm vi, tiến độ, chi phí, nguồn lực và các bên liên quan; tối ưu một mặt có thể làm mặt khác tệ đi. Thêm chức năng mà vẫn giữ ngày và ngân sách cũ không phải một điều chỉnh miễn phí. Trước khi nhận thay đổi cần biết ảnh hưởng và ai có quyền chấp thuận.~プロジェクトは有期性と独自性を持ち、定常業務と異なります。範囲、日程、費用、資源などは影響し合うため、機能追加の影響と承認を確認して調整します。~Tổ chức một đám cưới khác với dọn phòng hằng ngày. Thêm khách kéo theo chỗ ngồi, suất ăn và chi phí, không chỉ thêm vài tên vào danh sách.~一度の催しで参加者が増えると、席、食事、費用にも影響するような関係です。
WBS giúp thấy đầy đủ công việc theo cấu trúc phân cấp; nó không tự là lịch có ngày bắt đầu. Sau khi phân rã mới xem phụ thuộc, thời lượng, người và nguồn lực. Một gói việc cần đầu ra và trách nhiệm rõ để ước lượng và theo dõi. Scope creep xảy ra khi phạm vi âm thầm tăng mà không quản lý ảnh hưởng. Ghi rõ việc không thuộc phạm vi cũng giúp các bên thống nhất kỳ vọng.~WBSは必要な作業の分解で、日付付きの予定そのものではありません。成果と担当を明確にし、依存や期間を加えて日程を作ります。統制のない範囲拡大を防ぐため合意も必要です。~Danh sách món cần nấu chưa phải lịch nấu: còn biết món nào cần ướp trước, ai làm và bếp có bao nhiêu chỗ. Danh sách đầy đủ là nền, không phải toàn bộ kế hoạch.~献立一覧だけでは調理日程にならず、順序、人、設備の条件も必要です。
Quản lý rủi ro làm trước khi vấn đề xảy ra: nhận diện, đánh giá và chuẩn bị ứng phó. Quản lý chất lượng xác định tiêu chí và cách xác nhận; quản lý mua sắm điều phối nguồn từ ngoài; truyền thông xác định ai cần thông tin gì khi nào. Mỗi việc đều liên quan nhưng không thể thay bằng một báo cáo phần trăm hoàn thành. Một dự án “đúng lịch” vẫn có thể không đạt chất lượng hoặc người dùng chưa sẵn sàng.~リスクには事前の対応、品質には基準と確認、調達には外部との管理、情報共有には相手と時期の設計が必要です。進捗の数字一つではこれらすべてを評価できません。~Chuyến đi đúng giờ khởi hành vẫn có thể thất bại vì không có chỗ ngủ hoặc hành khách chưa được báo điểm đón. Thành công có nhiều điều kiện liên kết.~出発時刻が守れても宿泊や連絡が整わなければ旅行全体はうまく進みません。
Ước lượng phải có căn cứ và giả thiết: analog dựa dự án gần giống; bottom-up cộng từ việc nhỏ; function point đánh giá chức năng nhìn từ ngoài. Không nên coi số dòng mã hay số người luôn tỷ lệ đơn giản với thời gian. PMBOK là hệ tri thức được tổ chức khác nhau theo phiên bản; trong bài này dùng cách phân nhóm của tài liệu để hiểu vai trò, không gán mọi bảng cũ cho mọi bản mới.~類推、積上げ、機能に基づく規模評価では根拠が違います。工数と人数と期間を機械的に比例させません。PMBOKの整理は版によって異なり、教材の分類はその文脈で理解します。~Ước lượng xây nhà từ căn gần giống khác với cộng giá từng hạng mục. Cả hai có ích nhưng đều cần biết căn nhà và điều kiện có thực sự tương đồng không.~似た家の実績と、部材別の積上げでは見積りの根拠が違います。
'''
NOTES[53] = '''
WBS cho biết có những việc gì; sơ đồ mạng cho biết việc nào phụ thuộc việc nào. Nếu hai nhánh chạy song song, thời gian dự án là thời gian chờ nhánh dài hơn hoàn tất, không phải cộng mọi công việc. Critical path là đường dài nhất theo giả thiết của mô hình; công việc trên đó không có dư để trễ mà vẫn giữ hạn tính được. Sau khi rút ngắn một đường cần tính lại vì đường găng có thể đổi.~作業一覧と依存関係を区別します。並行経路があれば全体は長い方を待ちます。クリティカルパスはその条件での最長経路で、短縮後は別の経路が支配的になる場合があります。~Hai món nấu cùng lúc mất 7 và 5 phút thì bữa ăn chờ 7 phút, không phải 12. Rút món 5 phút xuống 3 phút chưa làm cả bữa sớm hơn.~同時に作る二品が7分と5分なら全体は7分で、短い方だけを縮めても完成時刻は変わりません。
Tính xuôi lấy thời điểm tiền nhiệm hoàn tất muộn nhất để tìm lúc bắt đầu sớm nhất; tính ngược lấy ràng buộc kế tiếp chặt nhất để tìm lúc muộn nhất. Total float là khoảng được trễ mà không đẩy ngày hoàn thành chung theo lịch đó. Dummy có thời lượng 0 để biểu diễn phụ thuộc, không phải một ngày công ẩn. Hãy ghi thời điểm ở mỗi nút rồi mới chọn đường, tránh cộng nhầm các nhánh tách–nhập.~順方向では先行の完了を待つため最大値、逆方向では後続を遅らせないため厳しい制約を使います。余裕と所要時間ゼロのダミーを分け、各時点を記入して確認します。~Một cuộc họp phải chờ đủ hai người đến nên chờ người đến sau; giờ rời nhà muộn nhất lại phải theo lịch trình gấp hơn ở phía sau.~全員集合には遅い到着を待ち、出発の限界は次の予定の厳しい方に合わせます。
EVM đưa ba con số về cùng đơn vị tiền để so được: PV là ngân sách của phần định làm tới mốc đó; EV là ngân sách của phần thật sự hoàn thành; AC là tiền thật đã chi. EV không phải doanh thu thu được, và AC không cho biết đã làm được bao nhiêu. Nếu chỉ thấy đã chi ít hơn kế hoạch, chưa thể kết luận tiết kiệm: có thể công việc cũng hoàn thành ít hơn nhiều.~PVは予定作業の予算、EVは完了作業を予算で測った値、ACは実際の費用です。支出が少ないことだけで良好とは言えず、完成した作業量も合わせて見ます。EVは売上ではありません。~Đặt mục tiêu lát 10 ô, mới lát 6 ô và trả tiền cho 7 ô: kế hoạch, giá trị đã hoàn thành và tiền đã chi là ba góc nhìn khác nhau.~10区画の予定、6区画の完成、7区画分の支出という三つの観点を分けます。
CV=EV−AC xét chi phí; SV=EV−PV xét mức hoàn thành so kế hoạch theo giá trị, không trực tiếp là số ngày trễ. CPI=EV/AC và SPI=EV/PV là các tỷ lệ, cần mẫu số khác 0. Tỷ lệ dưới 1 là dấu hiệu không thuận lợi theo chỉ số tương ứng. Khi đề yêu cầu dự báo chi phí cuối kỳ phải đọc thêm giả thiết về hiệu suất tương lai, không tự dùng một công thức dự báo cho mọi tình huống.~CVは費用差、SVは出来高による進捗差で、日数そのものではありません。CPIとSPIは異なる分母を使います。将来予測には今後の効率に関する仮定も必要です。~Đếm số ô còn thiếu cho biết mức chậm theo khối lượng, chưa tự cho biết còn mấy ngày: còn phụ thuộc năng lực làm tiếp. Chỉ số là tín hiệu cần giải thích trong bối cảnh.~不足した区画数だけでは残り日数は決まりません。今後の作業能力も関係します。
'''
NOTES[54] = '''
Dịch vụ IT được đánh giá qua giá trị người dùng nhận được, không chỉ qua máy có bật hay không. SLA biến kỳ vọng thành mức có thể thống nhất và đo được, gồm điều kiện đo và trách nhiệm. “Hỗ trợ nhanh” cần làm rõ phạm vi và thời điểm; cùng một con số khả dụng có thể khác ý nghĩa nếu khoảng đo khác nhau. ITIL cung cấp thực hành quản lý, không phải tên một phần mềm bắt buộc mua.~サービスは機器の稼働だけでなく利用者への価値で考えます。SLAでは水準と測定条件、責任を合意します。ITILは実践知識の枠組みであり、特定製品の購入を意味しません。~Thuê xe quan tâm chuyến đi đáp ứng nhu cầu, không chỉ xe còn nổ máy. Cần thống nhất giờ phục vụ và cách xử lý khi xe trục trặc.~車が動くことだけでなく必要な移動ができることと、その条件の合意が重要です。
Incident management ưu tiên khôi phục dịch vụ để giảm ảnh hưởng; problem management tìm nguyên nhân và ngăn tái diễn. Một workaround có thể cho người dùng làm việc lại dù nguyên nhân chưa sửa xong. Vì thế “incident đã đóng” không tự chứng minh vấn đề gốc biến mất. Service desk là điểm liên lạc để tiếp nhận và điều phối, không nhất thiết tự mình xử lý mọi lỗi kỹ thuật.~インシデント管理は早期復旧、問題管理は原因と再発防止です。回避策でサービスが戻っても根本問題が残ることがあります。サービスデスクは窓口であり、すべてを単独で修理する部署とは限りません。~Kẹt cửa thì mở lối tạm để người đi tiếp là khôi phục; tìm và sửa bản lề để không kẹt nữa là xử lý nguyên nhân.~仮の通路を開くことと、蝶番の原因を直すことは目的が違います。
Thay đổi dịch vụ có thể tạo sự cố mới nên cần đánh giá, phê duyệt và triển khai phù hợp. Change management xét thay đổi và rủi ro; release management đưa phiên bản được chấp thuận vào dùng; configuration management giữ thông tin thành phần và quan hệ. Khi một ứng dụng lỗi sau cập nhật, biết đúng phiên bản và phụ thuộc giúp khoanh vùng hơn nhiều so với chỉ ghi “đã nâng cấp”.~変更の判断、版の導入、構成と関係の記録は連携する別の役割です。どの版と設定が動いているかを把握すると変更後の問題も調べやすくなります。~Được phép thay động cơ, lịch đưa xe mới vào chạy và hồ sơ linh kiện đang lắp là ba phần của cùng một đợt thay đổi, không phải ba tên đồng nghĩa.~交換の承認、導入日程、部品構成の記録は別の仕事です。
Availability, capacity và continuity lần lượt chú ý khả năng dùng được, năng lực đáp ứng tải và khả năng tiếp tục/khôi phục khi gián đoạn lớn. Thêm CPU không tự sửa lỗi cấu hình làm dịch vụ ngừng, còn máy dự phòng chưa chắc đủ tải. Các kiểu service desk thay cách tổ chức nhân sự và địa điểm; follow-the-sun dùng múi giờ để chuyển ca, không có nghĩa một người phải làm liên tục cả ngày.~可用性、容量、継続性は異なる観点です。計算能力の追加だけですべての停止を解決しません。窓口の集中・分散や時差を利用した対応も、必要なサービス条件に合わせて組織します。~Nhà hàng cần mở cửa đúng lúc, đủ chỗ khi đông và có cách phục vụ khi bếp chính hỏng. Chỉ tăng bàn không giải quyết cả ba nhu cầu.~営業できること、混雑に対応できること、大きな障害でも続けることを分けて考えます。
'''
NOTES[55] = '''
Kiểm toán đặt câu hỏi có căn cứ: hệ thống và kiểm soát có đáp ứng tiêu chuẩn đã chọn không? Người kiểm toán cần bằng chứng và vị trí độc lập với đối tượng, không chỉ hỏi quản trị viên “mọi thứ ổn chứ?”. Independence nói về quan hệ và vị trí; objectivity nói về cách đánh giá không thiên vị. Biết nhiều kỹ thuật chưa tự giải quyết xung đột khi tự kiểm toán chính phần mình chịu trách nhiệm.~監査は基準と証拠による評価です。独立した立場と偏りのない判断の両方が必要で、技術力があっても自分の業務を独立に評価する立場とは限りません。~Trọng tài giỏi luật nhưng đồng thời là cầu thủ đội được chấm sẽ có vấn đề về vị trí. Độc lập và năng lực đều cần thiết.~ルールに詳しくても、選手と審判を兼ねれば立場の問題が残ります。
Quy trình đi từ xác định mục tiêu, phạm vi, thu thập thông tin, kiểm tra bằng chứng tới báo cáo và theo dõi cải tiến. Người kiểm toán báo phát hiện và kiến nghị, còn trách nhiệm quyết định và thực hiện cải tiến thuộc các vai trò quản lý/vận hành tương ứng. Nếu chỉ khuyên bằng cảm giác mà không chỉ ra căn cứ, người nhận khó đánh giá mức cần sửa. Follow-up xem biện pháp đã được thực hiện và giải quyết đúng điều được nêu chưa.~目的と範囲を定め、証拠を集め評価し、報告と改善確認につなげます。監査の提言と、管理側の改善実施の責任は区別します。指摘は根拠と結び付けます。~Bác sĩ ghi kết quả kiểm tra và hướng xử lý; không vì đưa khuyến nghị mà mọi thói quen sinh hoạt của người được khám tự đổi. Cần người thực hiện và lần kiểm tra lại.~診断と対処の実施と再確認はつながっていますが、同じ作業ではありません。
Internal control nằm trong công việc hằng ngày để giảm sai và gian lận, còn audit đánh giá các kiểm soát. Segregation of duties tránh một người tự tạo, tự duyệt rồi tự che dấu cùng một nghiệp vụ nhạy cảm. Quy tắc trên giấy cần có cơ chế thực thi và bằng chứng hoạt động. Đừng kết luận phân hai tài khoản nhưng vẫn cùng một người kiểm soát là đã phân tách trách nhiệm đầy đủ.~内部統制は日々の業務に組み込み、監査はその有効性を評価します。申請と承認などの役割を適切に分けます。アカウント名だけ分けても実際の責任分担が同じなら目的を満たすとは限りません。~Một người viết phiếu chi rồi tự ký cả ô duyệt chưa tạo được kiểm tra chéo, dù trên giấy có hai ô chữ ký.~同じ人が申請欄と承認欄の両方に署名しても、相互確認にはなりません。
Vận hành cần cả môi trường vật lý và kế hoạch thay đổi: điện, làm mát, chống sự cố, sao lưu và diễn tập phục hồi. UPS chỉ cấp điện tạm theo năng lực của nó, không thay kế hoạch điện vô hạn. Big-bang, phased và parallel migration đổi mức chuyển cùng lúc và khả năng đối chiếu, kèm chi phí và rủi ro khác nhau. Chạy song song cần cách xác định dữ liệu đúng, không chỉ bật cả hai hệ thống rồi để chúng tự khớp.~設備管理、保存と復旧、移行計画を合わせて考えます。UPSの給電には限界があります。一斉・段階・並行の移行は影響、確認方法、費用が違い、並行運用にも整合の管理が必要です。~Chuyển nhà một lần, chuyển từng phòng hay tạm giữ hai nơi có ưu nhược khác nhau. Giữ hai nơi vẫn phải biết đồ nào đang ở đâu và bản nào đang dùng.~一括の引越し、部屋別の移動、二拠点併用では管理する条件が違います。
'''
NOTES[14] = '''
OOP bắt đầu bằng việc gom trạng thái và thao tác có trách nhiệm với trạng thái đó vào cùng đối tượng. Lớp Account mô tả tài khoản nói chung; tài khoản của An là một instance có số dư cụ thể. Nếu ai cũng được ghi trực tiếp vào số dư, quy tắc “không rút quá số dư” dễ bị bỏ qua. Encapsulation cho phép kiểm tra quy tắc qua phương thức rút tiền và che cách lưu bên trong; không phải cứ viết một lớp là đã che giấu tốt.~クラスは共通の定義、インスタンスは具体的な実体です。残高を直接変更せず出金操作を通せば、残高不足などの規則を一か所で確認できます。データと責任をまとめ、内部の実装を隠すことがカプセル化の目的です。~Bản thiết kế căn hộ là lớp; từng căn hộ có người ở riêng là instance. Khách dùng cửa ra vào, không tự tháo tường để đi: đó là hình dung cho giao diện có kiểm soát, không phải mọi thuộc tính đều phải bí mật tuyệt đối.~設計図と実際の部屋を分け、決めた入口から利用するイメージです。すべての情報を無条件に隠すという意味ではありません。
Kế thừa mô tả quan hệ “là một loại”: SavingsAccount là một Account. Lớp con có thể dùng đặc trưng chung và định nghĩa lại thao tác phù hợp. Đa hình cho phép cùng gọi một thao tác trên giao diện chung mà hành vi dựa vào đối tượng thực tế: draw của Circle khác draw của Rectangle. Đừng dùng kế thừa chỉ vì hai lớp có vài dòng mã giống nhau; quan hệ mô hình phải hợp lý.~継承は上位の性質を下位へ引き継ぐ関係です。同じdrawでも実際の図形に応じた処理になるのが多態性です。単なるコードの共通部分だけでなく、「一種である」という関係が適切か考えます。~Cùng yêu cầu “phát ra tiếng” nhưng chó sủa, mèo kêu. Người gọi dùng cùng yêu cầu, đối tượng nhận quyết định cách đáp; không cần người gọi tự kiểm tra từng loài để viết mọi trường hợp.~同じ「鳴く」という操作でも犬と猫で動作が違います。呼出し側は共通の操作を使います。
Class diagram là góc nhìn cấu trúc: lớp nào có thuộc tính, thao tác và quan hệ nào. Multiplicity nằm ở đầu quan hệ cho biết với một đối tượng phía kia có bao nhiêu đối tượng đầu này. Customer 1 — Order 0..* nghĩa là mỗi đơn thuộc một khách, một khách có thể chưa có hoặc có nhiều đơn. Sơ đồ này không diễn tả rằng đơn đầu tiên phải tạo trước khi khách tồn tại, cũng không thể đọc như timeline.~クラス図は静的な構造を示します。多重度は反対側の一つに対していくつ対応するかを表します。顧客1と注文0..*なら一顧客に0件以上の注文が対応し、時間順序を示す図とは異なります。~Sơ đồ phòng ban cho biết ai thuộc nhóm nào, không cho biết sáng nay ai gọi điện trước. Muốn xem diễn tiến phải đổi góc nhìn.~組織図で所属は分かっても、今日の電話の順序までは分からないのと同じです。
UML có nhiều loại sơ đồ vì một hình không thể trả lời mọi câu hỏi. Use case hỏi ai dùng chức năng gì; sequence hỏi các bên gửi thông điệp theo thứ tự nào; activity hỏi công việc rẽ nhánh và chạy ra sao; state machine hỏi một đối tượng đang ở trạng thái nào và sự kiện gì làm đổi trạng thái. Khi giải bài, viết câu hỏi cần trả lời trước rồi chọn sơ đồ, thay vì nhớ biểu tượng mà bỏ mục đích.~ユースケースは利用者と機能、シーケンスは通信順、アクティビティは活動の流れ、状態機械は状態と遷移を表します。何を知りたいかを先に決めると図の選択に根拠ができます。~Bản đồ, thời gian biểu và danh sách trạng thái chuyến xe đều nói về xe buýt nhưng trả lời những câu hỏi khác nhau. Không có một sơ đồ tốt nhất cho mọi mục đích.~路線図、時刻表、運行状態は同じバスについて別の問いに答える資料です。
'''
NOTES[39] = '''
Bảo mật không chỉ là giữ kín. CIA tách ba mục tiêu: ai được đọc, nội dung có chính xác đầy đủ và có dùng được khi cần. Một dịch vụ công khai có thể không cần giữ bí mật trang giới thiệu nhưng vẫn rất cần tính toàn vẹn và khả dụng. Đọc tình huống theo tác động trực tiếp: sửa số tiền là vấn đề integrity; người có quyền không vào được là availability; lộ danh sách khách là confidentiality.~CIAは読める人、内容の正確さ、必要時の利用可能性という別の目標です。公開情報でも改ざん防止と利用継続は重要です。状況の直接の影響を見て特性を判別します。~Một tủ hồ sơ cần đúng người được mở, giấy bên trong không bị sửa sai và khi có việc phải lấy được. Chỉ khóa tủ thật chặt nhưng làm mất chìa vẫn chưa bảo vệ đủ ba mặt.~書庫は入れる人、書類の正しさ、必要時に取り出せることの三つを考えます。
Tài sản là thứ cần bảo vệ; đe dọa là nguyên nhân có thể gây hại; lỗ hổng là điểm yếu cho đe dọa khai thác; rủi ro xét khả năng và hậu quả trong bối cảnh đó. Mật khẩu yếu không phải bản thân kẻ tấn công; cháy không phải một loại dữ liệu. Tách bốn thành phần giúp chọn đúng biện pháp: vá lỗ hổng, hạn chế tiếp cận hay giảm thiệt hại có thể tác động vào những mắt xích khác nhau.~資産、脅威、脆弱性、リスクを区別します。弱いパスワードは弱点、攻撃者の行為は脅威で、発生可能性と影響を含めてリスクを評価します。対策がどこに作用するかも整理できます。~Xe là tài sản, trộm là đe dọa, khóa hỏng là điểm yếu; nguy cơ mất xe còn phụ thuộc nơi để và tổn thất nếu mất. Không thể sửa “trộm” bằng thay tên tài sản.~自転車、盗難、壊れた鍵、その場所での損失可能性を分けると対策の意味が分かります。
Không phải rủi ro nào cũng xử lý bằng cùng một công cụ. Tránh là bỏ hoạt động sinh rủi ro; giảm là hạ khả năng hoặc ảnh hưởng; chuyển/chia sẻ là phân bổ gánh nặng theo cơ chế như bảo hiểm; giữ là quyết định chấp nhận. Mua bảo hiểm không làm dữ liệu không bao giờ rò rỉ, và “chấp nhận” không nên là quên theo dõi. Sau biện pháp vẫn có residual risk cần người có thẩm quyền biết và đánh giá.~回避、低減、移転・共有、保有は対応方針の違いです。保険は事故そのものを無くしません。対策後にも残留リスクがあり、受け入れる判断と継続的な把握が必要です。~Áo mưa làm giảm bị ướt, hủy chuyến đi tránh nguy cơ trên chuyến đó, bảo hiểm chia sẻ thiệt hại. Ba lựa chọn không làm cùng một việc.~雨具、外出中止、保険では、リスクに働き掛ける方法が異なります。
ISMS biến bảo vệ thông tin thành công việc có trách nhiệm, chính sách, đánh giá và cải tiến liên tục, chứ không chỉ mua thiết bị rồi xong. PDCA buộc kiểm tra đối sách có đạt mục tiêu hay cần sửa. BCP nêu cách duy trì hoặc khôi phục nghiệp vụ quan trọng; BCM duy trì cả năng lực tổ chức cho việc đó qua cập nhật và luyện tập. Có kế hoạch nhưng chưa thử thực hiện vẫn để lại điều chưa biết.~ISMSは責任、方針、評価、改善を組織的に回す仕組みです。BCPは事業継続の計画、BCMは計画の更新や訓練を含む継続的な管理です。書面だけで実行可能性が証明されるわけではありません。~Kế hoạch thoát hiểm treo trên tường khác với cả đội biết lối ra và từng diễn tập. Hệ thống quản lý phải giúp kế hoạch trở thành hành động được kiểm tra.~避難図があることと、実際に避難できることは違います。訓練と見直しが計画を使えるものにします。
'''
NOTES[40] = '''
Phân loại mã độc bằng hành vi chính để tránh học tên rời rạc. Worm chú trọng tự lan; Trojan ngụy trang có ích để được chạy; spyware lén thu thập; ransomware khóa hoặc mã hóa để đòi tiền. Một chương trình thực tế có thể có nhiều hành vi nên các nhãn không phải luôn loại trừ tuyệt đối. Trong bài hỏi tên, bám dấu hiệu được đề nhấn mạnh thay vì chỉ thấy chữ “mã độc” rồi chọn loại quen thuộc.~ワームの増殖、トロイの木馬の偽装、スパイウェアの収集、ランサムウェアの身代金要求という特徴で整理します。実際には複数の性質を持つ場合もあるので、設問で強調された動作を確認します。~Kẻ giả thợ sửa chữa, người lén ghi chép và người khóa cửa đòi tiền đều gây hại nhưng thủ đoạn khác nhau. Nhận đúng hành vi giúp chọn biện pháp phù hợp.~修理人のふり、盗み見、施錠して金銭要求では手口が違います。
Tấn công có thể khai thác con người thay vì lỗi phần mềm. Phishing giả người đáng tin để dẫn tới chỗ nhập thông tin; social engineering rộng hơn, gồm gọi điện giả danh hay lợi dụng thói quen; shoulder hacking nhìn trộm trực tiếp. Thư biết tên và công việc của người nhận không tự chứng minh nó thật: đó cũng là dữ liệu có thể dùng để làm thư lừa thuyết phục hơn.~人の判断や行動も攻撃対象です。フィッシング、電話での詐称、肩越しの盗み見は方法が異なります。氏名や業務内容を知っていることだけでは送信者の正当性を確認できません。~Biết tên bạn để nói chuyện thân quen không thay cho giấy tờ xác minh. Mức độ giống người quen và bằng chứng xác thực là hai thứ khác nhau.~親しげに名前を呼ぶことと、正しい本人確認の証拠は別です。
Bài tấn công mật khẩu nên lập bảng hai trục: có đổi ID không, có đổi mật khẩu không, lấy ứng viên từ đâu. Brute force thử nhiều ứng viên cho một mục tiêu; reverse brute force giữ mật khẩu rồi đổi nhiều ID; list attack dùng các cặp đã rò rỉ. DDoS lại đánh khả dụng bằng nhiều nguồn, không phải một phương pháp đoán mật khẩu. Đừng gom mọi lần đăng nhập thất bại thành cùng một kiểu.~IDとパスワードのどちらを変えるか、候補をどこから得るかで分類します。総当たり、逆総当たり、漏えいした組の利用は異なります。多数の発信元からサービスを妨害するDDoSとも区別します。~Thử nhiều chìa vào một ổ, thử một chìa vào nhiều ổ và dùng danh sách chìa–ổ đã bị đánh cắp là ba chiến thuật khác nhau.~一つの錠に多数の鍵、一つの鍵で多数の錠、盗んだ対応表の利用は別の方法です。
SQL injection làm dữ liệu nhập bị diễn giải thành một phần lệnh SQL; XSS làm nội dung script chạy trong trình duyệt người xem; DNS poisoning làm thông tin tên trỏ sai địa chỉ. Chúng tác động vào các tầng và bên thực thi khác nhau. Khi gặp tình huống hãy xác định dữ liệu độc hại đi vào đâu, bên nào diễn giải nó và tài sản nào bị ảnh hưởng; từ đó chọn biện pháp tương ứng, không dùng một chữ “lọc” cho mọi lỗi.~SQL、ブラウザ、DNSでは不正な入力が解釈される場所が違います。入力先、実行する主体、影響を受ける対象を順に整理すると、攻撃と対策の関係を説明できます。~Ghi lệnh giả vào phiếu bếp khác với dán thông báo giả cho khách và sửa bảng chỉ đường. Cùng là đánh lừa nhưng nhắm vào người xử lý khác nhau.~調理指示への混入、客向け掲示の偽装、案内板の書換えでは、だます相手が違います。
'''
NOTES[41] = '''
Mật mã cần tách nội dung, thuật toán và khóa. Với khóa chung, hai bên dùng cùng bí mật nên xử lý dữ liệu hiệu quả nhưng phải chia sẻ khóa đúng cách. Với khóa công khai, công bố một khóa không có nghĩa công bố khóa bí mật đi kèm. Khi gửi bí mật cho B theo mô hình cơ bản, A dùng khóa công khai của B và B dùng khóa bí mật của mình giải mã: chọn khóa theo **ai phải đọc được**, không theo ai đang cầm thông điệp.~平文、アルゴリズム、鍵を分けて考えます。共通鍵は共有方法が課題になります。Bだけに読ませる公開鍵暗号ではBの公開鍵で暗号化しBの秘密鍵で復号します。誰に読ませたいかが鍵選択の基準です。~Hộp thư có khe ai cũng bỏ thư vào nhưng chỉ chủ hộ có chìa lấy thư ra giúp hình dung khóa công khai và bí mật. Đây là ví von, không phải hai khóa vật lý thực sự hoạt động như thuật toán.~誰でも投入でき、所有者だけが開けられる箱の例です。物理的な仕組みを暗号方式そのものと同一視はしません。
Mã hóa kết hợp dùng thế mạnh của hai cơ chế: dữ liệu lớn được xử lý bằng khóa chung, còn việc bảo vệ hoặc thiết lập khóa dùng cơ chế phù hợp của hệ thống. Đừng hiểu mọi byte đều cần mã hóa hai lần bằng hai thuật toán. Trong mô hình gửi khóa của sách, người nhận mở phần khóa bằng khóa bí mật rồi dùng khóa chung mở nội dung. Khi đếm khóa giữa n người, phải đọc giả thiết chia sẻ theo từng cặp hay mỗi người có một cặp khóa công khai.~ハイブリッド方式では本文と鍵の保護で役割を分担します。全データを二重に同じ流れで処理するという意味ではありません。鍵の個数を求める問題は、二者間共有か各人の鍵対かという前提を先に確認します。~Một hộp lớn khóa bằng chìa dùng một lần và một hộp nhỏ bảo vệ chìa đó giúp hình dung phân công công việc. Mở hộp nhỏ và mở nội dung là hai bước.~大きな荷物とその鍵を保護する小箱で、役割を分けるイメージです。
Hàm băm tính một digest từ dữ liệu, không phải mã hóa để người nhận giải ngược bằng khóa. Dữ liệu dài ngắn khác nhau vẫn cho độ dài đầu ra theo thuật toán. Hai dữ liệu khác nhau có thể có cùng giá trị băm về mặt toán học; yêu cầu an toàn là khó tìm các cặp như vậy với thuật toán phù hợp. Chỉ có hash gửi cùng file qua cùng đường không tin cậy chưa đủ chứng minh người gửi, vì cả file và hash đều có thể bị thay.~ハッシュは復号のための暗号文ではありません。出力長は方式によって決まり、異なる入力の衝突は数学的には存在します。改変者がファイルとハッシュの両方を置き換えられるなら、それだけで送信者を証明できません。~Dấu kiểm tra giống dấu tóm tắt giúp so nội dung; nó không tự là con dấu độc quyền của một người. Cần thêm cơ chế gắn với danh tính khi muốn chứng minh ai tạo.~内容の要約のような値と、特定の人の署名は役割が違います。
Chữ ký số nhắm tới kiểm tra nguồn gốc và sửa đổi; không tự làm nội dung bí mật. A ký bằng khóa bí mật A, bên nhận kiểm tra bằng khóa công khai A. Chứng thư liên kết một chủ thể với khóa công khai, CA xác nhận liên kết đó trong mô hình tin cậy. Vì vậy phải kiểm tra không chỉ phép xác minh toán học mà cả khóa đang được gán cho ai. Khóa công khai của B không xác minh chữ ký của A chỉ vì B là người nhận.~署名は送信者と改ざんの検証であり、内容の秘匿とは別です。Aの秘密鍵で署名しAの公開鍵で検証します。証明書と認証局は主体と公開鍵の対応を確認する仕組みで、使っている鍵が誰のものかも重要です。~Đọc được thư có chữ ký vẫn không làm mất ý nghĩa chữ ký: chữ ký giúp kiểm tra ai ký, còn phong bì kín là chuyện khác. Không lấy chữ ký người nhận để kiểm tra người gửi.~署名入りの手紙を読めることと、署名が正しいかは別です。受取人の署名で差出人を確認しません。
'''
NOTES[42] = '''
Một lớp phòng thủ không nhìn thấy mọi loại tấn công. Firewall kiểm soát luồng theo chính sách; WAF nhìn yêu cầu Web; IDS phát hiện và cảnh báo; IPS có khả năng ngăn luồng theo cơ chế được triển khai. “Có thiết bị” chưa đủ: cần đặt đúng chỗ, cấu hình và theo dõi. Cũng không nên hình dung IDS luôn là bản yếu của IPS: quan sát, chặn và ảnh hưởng đến dịch vụ là những trách nhiệm khác nhau.~ファイアウォール、WAF、IDS、IPSでは検査対象と動作が異なります。導入の有無だけでなく配置、規則、監視を考えます。検知して通知することと、通信を止めることは役割と運用上の影響が違います。~Cổng kiểm soát người ra vào, người đọc giấy tờ và chuông báo trộm không làm cùng một việc. Ghép nhiều lớp chỉ hữu ích khi hiểu lớp nào xử lý điều gì.~入口の制限、書類の確認、警報はそれぞれ役割が違います。
DMZ tách dịch vụ công cộng khỏi khu vực nội bộ để giới hạn đường đi và ảnh hưởng khi có sự cố; không phải vùng được phép bỏ bảo vệ. VPN tạo đường kết nối riêng trên hạ tầng chung; TLS bảo vệ kênh của phiên truyền thông thích hợp. Dù kênh được mã hóa, người có quyền vẫn có thể dùng sai hoặc đầu cuối có thể bị nhiễm mã độc. Phải phân biệt bảo vệ đường đi và bảo vệ máy ở hai đầu.~DMZは公開領域と内部を分ける構成で、安全対策を不要にする領域ではありません。VPNやTLSによる通信路の保護と、利用者や端末の安全性は別に考えます。~Phòng tiếp khách tách khỏi kho hồ sơ giúp hạn chế khách đi sâu, nhưng không vì thế cho phép để cửa phòng tiếp khách không kiểm soát.~応接室を書庫から分けても、応接室の管理が不要になるわけではありません。
Authentication hỏi “bạn là ai?”, authorization hỏi “bạn được làm gì?”. Sau đăng nhập vẫn cần giới hạn quyền theo công việc. MFA đếm các **loại yếu tố**: biết, có, là; hai mật khẩu không tự thành hai yếu tố độc lập. Sinh trắc hay OTP cũng có phạm vi và cách triển khai cụ thể, nên không kết luận có chúng là mọi hành vi đều được cấp quyền.~認証と認可を分けます。ログイン後にも最小権限が必要です。多要素は知識、所持、生体など種類の組合せであり、二つの知識情報を入力するだけでは異なる二要素になりません。~Thẻ nhân viên chứng minh bạn thuộc công ty không cho phép mở mọi phòng. Còn hai câu hỏi chỉ dựa trí nhớ vẫn là kiểm tra cùng một loại năng lực.~社員証で本人を確認しても全室への立入りは許されません。記憶を二度尋ねても要素の種類は同じです。
Vận hành bảo mật là một chu trình: biết tài sản và cấu hình, sửa lỗi phù hợp, phát hiện dấu hiệu, phản ứng và khôi phục. Log cần mốc giờ để ghép sự kiện; cập nhật bản vá cần kiểm tra và triển khai có kiểm soát. MDM quản lý tập trung thiết bị di động, remote wipe là một khả năng xử lý dữ liệu từ xa nhưng còn phụ thuộc điều kiện thiết bị. Không nên đợi mất máy mới tìm hiểu đã cấu hình được gì.~資産把握、修正、検知、対応、回復をつなげて考えます。ログには時刻の整合が役立ち、パッチには適切な確認と適用が必要です。MDMや遠隔消去も事前の設定と動作条件を把握して運用します。~Bảo vệ tòa nhà không kết thúc ở lắp khóa: còn danh sách chìa, nhật ký ra vào, kiểm tra cửa hỏng và phương án khi mất chìa.~鍵を付けた後にも鍵の管理、入退室の記録、故障時の対応が必要です。
'''
NOTES[32] = '''
Chuyển tiền không phải hai thao tác độc lập “trừ A” và “cộng B”: người dùng cần cả hai cùng thành công. Transaction gom chúng thành một đơn vị công việc. Atomicity không yêu cầu mọi lệnh chạy trong cùng một nhịp, mà yêu cầu kết quả cuối không để lại trạng thái chỉ làm được một nửa. Consistency xét các quy tắc như tổng tiền hay ràng buộc khóa; ứng dụng vẫn phải viết thao tác đúng, DBMS không tự hiểu mọi luật kinh doanh.~送金は引落しと入金を一つの取引として扱います。原子性は物理的な同時実行ではなく、一部だけの結果を残さない性質です。一貫性には制約を保つ適切な取引処理も必要で、DBMSが業務規則を自動で理解するわけではありません。~Hai vế của phiếu chuyển tiền phải đi cùng nhau. Không thể coi việc xé đôi phiếu và chỉ lưu một nửa là giao dịch hoàn chỉnh.~振替伝票の二つの側を一組として扱うイメージです。半分だけ記録して完了とはしません。
COMMIT xác nhận kết quả, ROLLBACK hủy phần chưa xác nhận của giao dịch. Isolation giải quyết việc nhiều giao dịch xen kẽ: mỗi thao tác riêng đúng vẫn có thể cho tổng thể sai nếu hai người cùng đọc giá trị cũ rồi cùng ghi đè. Khi đọc bài, ghi rõ giao dịch nào đọc gì ở thời điểm nào. “Có nhiều người cùng dùng” không đồng nghĩa mọi mức cô lập đều cho cùng một hành vi.~COMMITは確定、ROLLBACKは未確定の変更の取消しです。複数の取引が古い値を読んで上書きすると、各計算が正しくても更新が失われることがあります。どの取引がいつ何を読んだかを追い、分離レベルの違いにも注意します。~Hai người sửa hai bản sao của cùng một danh sách rồi lần lượt chép đè có thể làm mất phần người trước vừa thêm. Lỗi ở cách phối hợp, không nhất thiết ở phép cộng.~同じ一覧の写しを別々に編集して上書きすると、先の追加が消えます。計算ではなく共同作業の順序の問題です。
Khóa giúp phối hợp truy cập: khóa chia sẻ phục vụ đọc trong mô hình cơ bản, khóa độc quyền chặn thao tác xung đột khi cập nhật. Tuy nhiên khóa không có nghĩa là hệ thống hết vấn đề: A giữ X chờ Y, B giữ Y chờ X tạo vòng chờ deadlock. Hai pha khóa nói về giai đoạn lấy thêm khóa và giai đoạn nhả khóa, không phải hai pha xác nhận của giao dịch phân tán.~共有ロックと排他ロックで競合する操作を調整します。ただし互いの資源を待つ循環ができればデッドロックになります。二相ロックの二段階と、分散取引の二相コミットは別の仕組みです。~Hai người mỗi người giữ một chìa khóa và đều đợi chìa còn lại thì không ai tiến được. Có khóa giúp bảo vệ, nhưng cần cả quy tắc sử dụng khóa.~二人が一つずつ鍵を持ち、互いの鍵を待つと進めません。鍵を使う順序も重要です。
Durability yêu cầu kết quả đã xác nhận được giữ qua sự cố theo cơ chế của hệ thống. Log cung cấp dấu vết trước/sau cập nhật để phục hồi: undo loại tác động chưa hoàn tất; redo áp dụng lại tác động cần giữ. Sao lưu là điểm xuất phát cho một số loại phục hồi, còn log giúp tiến đến mốc phù hợp. Đừng dùng “rollback” làm tên chung cho mọi việc phục hồi sau hỏng đĩa.~永続性は確定済みの結果を障害後にも保持する性質です。ログを利用し、未完了の変更を取り消すundoと必要な更新を再実行するredoを区別します。バックアップとログは復旧で役割を分担します。~Bản chụp sổ kế toán và nhật ký phát sinh là hai thứ bổ sung nhau: bản chụp cho mốc nền, nhật ký cho biết sau đó chuyện gì đã xảy ra.~帳簿の保存版が基準時点、取引日誌がその後の変化を示すという関係です。
'''
NOTES[33] = '''
AI là phạm vi rộng; machine learning là cách để hệ thống rút ra quy luật từ dữ liệu thay vì mọi quy tắc đều do người viết tay. Deep learning dùng mạng neural nhiều lớp, không đồng nghĩa mọi AI đều là deep learning. Để hiểu một bài toán học máy, trước tiên xác định đầu vào là gì và cần đầu ra gì: dự đoán giá, nhận diện loại ảnh hay tìm các nhóm khách khác nhau là các mục tiêu khác nhau.~AI、機械学習、深層学習は範囲が異なります。機械学習はデータから規則を学び、深層学習は多層のニューラルネットワークを使います。まず入力と必要な出力を明確にし、どの課題を解くかを確認します。~Dạy bằng nhiều bài mẫu khác với viết sẵn một danh sách mệnh lệnh cho mọi trường hợp. Nhưng “đã xem nhiều mẫu” chưa chứng minh đã hiểu đúng mẫu mới.~例題から学ぶことと、全場合の規則を書いておくことは違います。多くの例を見たことだけでは未知の例への正しさは保証されません。
Học có giám sát có dữ liệu đầu vào kèm đáp án mong muốn; phân loại dự đoán nhãn, hồi quy dự đoán số. Học không giám sát tìm cấu trúc khi không có sẵn nhãn đúng cho từng ví dụ, chẳng hạn gom cụm khách hàng. Học tăng cường dựa phản hồi thưởng trong chuỗi hành động. Từ “học” giống nhau nhưng thông tin phản hồi được cung cấp khác nhau; đọc xem đề có nhãn, có thưởng hay chỉ có đặc trưng.~教師あり学習には正解ラベルがあり、分類は種類、回帰は数値を予測します。教師なし学習はラベルなしで構造を探し、強化学習は行動に対する報酬を使います。与えられる情報の違いで判別します。~Chấm bài bằng đáp án, tự chia đồ vật thành nhóm và luyện trò chơi qua điểm thưởng là ba cách nhận phản hồi khác nhau.~正解表で学ぶ、似た物を自分でまとめる、ゲームの報酬で行動を変える、という違いです。
Một mô hình có thể nhớ dữ liệu huấn luyện quá kỹ nhưng dự đoán kém trên dữ liệu mới: đó là overfitting. Vì vậy không đánh giá chỉ bằng kết quả trên chính bộ đã dùng để học. Tách dữ liệu phù hợp giúp kiểm tra khả năng khái quát, và cần tránh để thông tin đáp án của tập đánh giá lọt vào khâu huấn luyện. Thu thập nhiều dữ liệu sai hoặc dùng sai mục tiêu không tự tạo ra mô hình tốt.~訓練データに合いすぎて未知データに弱くなるのが過学習です。学習に使ったデータでの成績だけでは評価せず、独立した評価と情報漏れの防止が必要です。量だけでなくデータと目的の適切さを確認します。~Học thuộc đáp án một đề rồi làm lại được điểm cao chưa chứng minh giải được đề khác. Bài kiểm tra cần có điều chưa được dùng để luyện.~同じ問題集の答えを覚えて高得点でも、別の問題を解けるとは限りません。
Phần ôn DB trong bài này nối quy trình từ thiết kế đến vận hành: E-R xác định đối tượng và quan hệ, chuẩn hóa tổ chức bảng, SQL lấy dữ liệu, transaction bảo vệ các cập nhật liên quan. Chúng không thay thế nhau. Trước khi lấy dữ liệu làm đầu vào cho AI, vẫn phải hiểu ý nghĩa cột, giá trị thiếu và cách các bảng được ghép; JOIN sai có thể nhân bản quan sát và làm sai cả thống kê lẫn dữ liệu học.~E-R、正規化、SQL、トランザクションは設計から運用までの異なる役割です。AIに渡すデータでも列の意味、欠損、結合関係を理解します。誤った結合で行を増やすと分析の前提も変わってしまいます。~Nấu ăn ngon không cứu được việc lấy nhầm nguyên liệu. Mô hình phía sau cũng không tự sửa mọi sai sót của dữ liệu chuẩn bị phía trước.~調理方法だけでなく材料の選び方が重要なように、モデル以前のデータの意味を確認します。
'''
NOTES[34] = '''
Mạng cần cả đường truyền lẫn quy tắc chung: cùng nối dây chưa đủ để hai máy hiểu nhau. Chia thông điệp thành packet giúp truyền và chuyển tiếp theo các đơn vị; header chứa thông tin điều khiển để thiết bị xử lý. Tốc độ đường truyền là khả năng danh định, còn tốc độ dữ liệu hữu ích còn chịu hiệu suất và thông tin phụ. Vì thế bài tính phải thống nhất bit/byte và dùng đúng tốc độ thực tế theo giả thiết.~配線だけでなく通信規約も必要です。データはヘッダーを持つ単位で送られます。回線の公称速度と実効的なデータ速度を区別し、転送計算では単位と効率をそろえます。~Đường lớn chưa bảo đảm xe chở hàng hữu ích đi hết công suất: còn biển báo, thời gian chờ và phần chở bao bì. Đây là hình dung về overhead, không phải mọi đường mạng đều ứng xử như đường xe.~道路の幅と実際に運べる荷物量が同じでないように、通信にも制御用の情報や効率の違いがあります。
OSI chia trách nhiệm để khi thiết kế hoặc tìm lỗi không phải xem cả hệ thống như một khối. Tầng vật lý xử lý tín hiệu; liên kết dữ liệu xử lý khung trên liên kết; mạng xử lý chuyển gói qua mạng; giao vận phục vụ truyền thông đầu cuối; các tầng trên xử lý phiên, biểu diễn và dịch vụ ứng dụng. Khi dữ liệu đi xuống, các lớp bổ sung thông tin của mình; máy nhận xử lý theo chiều ngược lại.~OSIは責任を階層に分けます。信号、リンク上のフレーム、ネットワーク間のパケット、端点間の通信、上位のサービスを分担します。送信側で各層の情報を加え、受信側は対応する情報を処理します。~Gửi kiện hàng gồm hàng bên trong, phiếu giao và bao vận chuyển. Mỗi đơn vị xử lý phần thông tin cần cho nhiệm vụ của mình, không cần hiểu toàn bộ nội dung hàng.~荷物、伝票、運送用の包装のように、各担当が必要な情報を見て処理するイメージです。
Mô hình tầng giúp phân biệt địa chỉ theo phạm vi: MAC dùng trên chặng liên kết, IP phục vụ đường đi qua mạng, số cổng phân biệt dịch vụ hoặc đầu cuối trên máy. Khi một gói qua router, khung của chặng tiếp theo được tạo cho liên kết tiếp theo; không nên hiểu MAC đích của một khung luôn là máy cuối tận bên kia Internet. Hãy hỏi “đang xét thông tin của tầng nào và chặng nào?”.~MAC、IP、ポートは識別する範囲が違います。ルータを越える際には次のリンクに合わせてフレームが作られます。一つのフレームの宛先MACを、常に遠方の最終ホストのものと考えないようにします。~Địa chỉ người nhận trên đơn hàng và tên trạm trung chuyển gần nhất phục vụ hai việc khác nhau. Giao cho trạm tiếp theo không có nghĩa trạm đó là người nhận cuối.~最終宛先の住所と次の中継所の指定は役割が違います。
Thiết bị được phân biệt bằng thông tin dùng để quyết định chuyển tiếp: repeater tái tạo tín hiệu, bridge/L2 switch xét MAC, router xét mạng IP. Một thiết bị thực tế có thể gộp nhiều chức năng, nên khi đề hỏi chức năng phải theo mô hình được nêu, không theo hộp thiết bị ở nhà. Kết nối vật lý thành công cũng chưa chứng minh DNS, định tuyến hay dịch vụ ứng dụng đang đúng.~リピータ、L2機器、ルータでは転送判断に使う情報が異なります。実際の製品は複数機能をまとめることもあるため、設問の機能に着目します。物理接続だけで上位の通信成功まで保証されません。~Một tòa nhà có thể vừa bưu cục vừa kho nhưng công việc phân thư vẫn khác công việc giữ hàng. Đừng dùng tên cả tòa nhà để thay cho vai trò đang được hỏi.~同じ建物に複数の仕事があっても、分類と保管の役割は区別するのと同じです。
'''
NOTES[35] = '''
IPv4 có 32 bit, viết thành bốn số thập phân chỉ là cách đọc thuận tiện. Prefix /n nói n bit đầu thuộc phần mạng, phần còn lại dành cho địa chỉ trong mạng đó. Mask có bit 1 ở phần mạng và 0 ở phần host; IP AND mask giữ phần mạng và xóa phần host. Bởi vậy hai IP trông gần nhau chưa chắc cùng subnet nếu mask khác; phải xét cặp IP và prefix cùng lúc.~IPv4は32ビットで、/nは先頭nビットをネットワーク部とする指定です。IPとマスクのANDでホスト部を0にします。アドレスの見た目だけでなくマスクも合わせて同一ネットワークか判断します。~Số nhà phải đi cùng tên đường: cùng số 10 chưa chắc cùng khu. Prefix giúp xác định phần địa chỉ dùng chung của một nhóm.~番地だけでなく町名も必要なように、共有する範囲の情報を合わせて考えます。
Chia subnet nghĩa là dùng thêm bit cho phần mạng, nên mỗi khối nhỏ lại và số khối tăng. Với /26, còn 6 bit host nên có 64 địa chỉ trong một khối; trong subnet IPv4 thông thường của bài học, loại địa chỉ mạng và broadcast còn 62 host. Đừng áp dụng máy móc công thức trừ 2 cho /31, /32 hay IPv6. Muốn tìm khối chứa một địa chỉ, tính mạng bằng AND hoặc xét ranh giới khối.~プレフィックスを長くすると一つの網のアドレス数は減ります。/26はホスト部6ビットで64個、通常の設問ではネットワークとブロードキャストを除き62個です。この引算を例外的な範囲へ無条件に広げません。~Chia một dãy ô thành nhiều phòng nhỏ hơn không làm tổng số ô tăng: mỗi phòng ít chỗ đi nhưng có nhiều phòng hơn. Các ô dành cho vai trò đặc biệt vẫn cần xét.~同じ区画を小さい部屋へ分けると部屋数は増え、一部屋の枠は減ります。
IP phục vụ chuyển gói nhưng không tự cung cấp mọi bảo đảm cho dữ liệu ứng dụng. TCP xử lý luồng tin cậy, thứ tự và truyền lại theo cơ chế của nó; UDP truyền datagram với ít cơ chế hơn, còn ứng dụng quyết định cách xử lý bổ sung. Đừng kết luận UDP “luôn nhanh hơn” hoặc TCP “không bao giờ mất kết nối”: hãy nhìn nhu cầu thứ tự, độ trễ và xử lý mất dữ liệu trong tình huống.~IPの配送と、TCP・UDPが提供する機能を区別します。TCPは順序や再送などを管理し、UDPでは必要な処理をアプリが担う場合があります。速さや信頼性を絶対的な一言で判断せず、用途を確認します。~Thư có theo dõi và xác nhận khác với phát từng tờ thông báo. Cách nào phù hợp phụ thuộc việc có cần biết đủ và đúng thứ tự hay không; không phải tờ thông báo tự nhiên không bao giờ thất lạc.~確認を伴う配送と単位ごとの配布を比べると、必要な保証によって選ぶ理由が分かります。
Địa chỉ private giúp dùng địa chỉ trong mạng riêng; NAT/NAPT xử lý chuyển đổi ở ranh giới khi cấu hình có dùng chúng. IPv6 mở rộng không gian địa chỉ nhưng không làm mọi cơ chế bảo mật tự xuất hiện. Khi bài cho một sơ đồ, hãy lần theo địa chỉ nguồn, đích và thiết bị trên từng chặng, đồng thời phân biệt bài tính địa chỉ với bài hỏi giao thức vận chuyển hay phân giải tên.~私用アドレス、変換、IPv6の役割を分けて整理します。IPv6はアドレス空間を広げますが、それだけで安全性の全課題を解決しません。図では各区間の送信元、宛先、装置を順に追います。~Số phòng nội bộ và địa chỉ bưu chính bên ngoài phục vụ hai phạm vi khác nhau. Đổi sang hệ thống đánh số lớn hơn không tự thay ổ khóa của căn phòng.~社内の部屋番号と外からの住所は範囲が違い、番号体系を広げても鍵の管理まで自動で解決しません。
'''
NOTES[36] = '''
Trước khi nhớ tên thiết bị, hãy nhìn nó dựa vào thông tin nào. Tái tạo tín hiệu là công việc tầng vật lý; học MAC và chọn cổng là công việc chuyển khung; chọn mạng đích và next hop là công việc định tuyến. Switch chỉ biết khung ở chặng LAN không vì thế có đủ thông tin để thay router nối các mạng IP. Hộp “router Wi-Fi” ở nhà có thể chứa nhiều vai trò trong cùng sản phẩm.~機器の区別は処理する情報で考えます。信号の再生、MACによるフレーム転送、IPによる経路制御は別の仕事です。家庭用の製品はこれらを組み合わせる場合があります。~Nhân viên nối điện, người phân thư trong tòa nhà và đơn vị chuyển hàng giữa thành phố dùng ba loại chỉ dẫn khác nhau. Cùng ở một quầy không làm nhiệm vụ giống nhau.~配線担当、建物内の配達担当、都市間の配送担当は判断に使う情報が違います。
Một máy gửi tới ngoài subnet thường giao khung cho default gateway; router tiếp tục tra bảng định tuyến để chọn chặng sau. Nếu cùng liên kết IPv4, máy có thể cần ARP để tìm MAC tương ứng. DNS không làm công việc tìm MAC này: DNS gắn với thông tin tên, ARP gắn với địa chỉ trên liên kết cục bộ. Ghi rõ thông tin “đã biết” và “cần tìm” sẽ giúp chọn đúng giao thức.~外部宛てでは通常デフォルトゲートウェイへ渡し、その先は経路表で転送します。同一リンクのIPv4に対応するMACはARPで調べます。名前からの情報取得であるDNSとは、既知の値と求める値が違います。~Biết tên cửa hàng để tra địa chỉ khác với biết địa chỉ trạm gần nhất để giao cho người vận chuyển. Hai lần tra đều hữu ích nhưng không trả cùng loại kết quả.~店名から住所を調べることと、次に渡す相手を特定することは違います。
DNS giải quyết “tên này tương ứng thông tin địa chỉ nào?”, DHCP giải quyết “máy này được cấp cấu hình mạng nào?”. Một máy đã có IP vẫn có thể không truy cập được bằng tên do cấu hình DNS; ngược lại DNS tồn tại không tự cấp IP cho máy mới. Khi chẩn đoán theo đề, thử tách kết nối theo IP, phân giải tên và quyền truy cập dịch vụ thay vì gọi chung tất cả là “mất mạng”.~DNSは名前に対応する情報、DHCPは端末へのネットワーク設定の配布です。IPがあっても名前解決は失敗し得ます。IP通信、名前解決、サービスの利用を分けて確認すると原因を整理できます。~Danh bạ điện thoại giúp tra tên ra số; quầy cấp số nội bộ cấp số cho nhân viên mới. Có danh bạ không có nghĩa nhân viên đã được cấp máy và số.~電話帳と内線番号の割当て窓口は役割が違います。
NAT đổi địa chỉ giữa các miền; NAPT dùng thêm số cổng để nhiều máy cùng chia sẻ một địa chỉ ngoài. Bảng ánh xạ giúp phản hồi quay về đúng máy bên trong. Đừng nhầm số cổng nguồn sau biến đổi với cổng dịch vụ đích: chúng không nhất thiết giống nhau. NAT cũng không phải tên khác của DNS hay một bảo đảm rằng ứng dụng không thể có lỗ hổng.~NATはアドレス、NAPTはポートも使って対応付けます。変換表で応答の戻り先を決めるため、変換した送信元ポートとサービスの宛先ポートを区別します。変換そのものはアプリの安全性を保証しません。~Nhiều người cùng gửi qua quầy lễ tân, quầy gắn số phiếu khác nhau để biết thư trả về cho ai. Địa chỉ quầy giống nhau nhưng số phiếu giữ các luồng riêng.~受付の共通住所に個別の受付番号を組み合わせ、戻ってきた返事を担当者へ渡すイメージです。
'''
NOTES[37] = '''
Khi mở một URL, nhiều vai trò phối hợp: lấy tên máy từ URL, tìm thông tin địa chỉ, thiết lập kết nối phù hợp rồi gửi yêu cầu HTTP. HTTP diễn tả yêu cầu–phản hồi của ứng dụng; HTTPS đặt trao đổi đó trong kênh TLS được bảo vệ. Tên giao thức không thay cho toàn bộ quá trình: DNS thành công chưa chứng minh Web server trả đúng, và mã hóa đường truyền chưa chứng minh nội dung website đáng tin.~URLから対象を決め、名前解決や接続を経てHTTPをやり取りします。HTTPSはHTTPをTLSで保護したものです。名前解決の成功とWebの応答、通信の保護とサイト内容の信頼性は区別します。~Tìm địa chỉ cửa hàng, đi tới nơi rồi hỏi mua là các bước khác nhau. Đi bằng xe kín bảo vệ cuộc trao đổi trên đường không có nghĩa cửa hàng nào cũng chân thật.~住所を調べて訪問し質問するのは別の段階です。道中の保護と相手自体の信頼性は別です。
GET thường yêu cầu lấy biểu diễn tài nguyên; POST gửi dữ liệu để phía máy chủ xử lý theo nghĩa của tài nguyên đó. HTTP không tự ghi nhớ mọi bước người dùng đã làm trước đó, nên ứng dụng thường dùng thông tin phiên, có thể qua cookie. Cookie là dữ liệu trình duyệt lưu và gửi lại theo điều kiện, không tự đồng nghĩa toàn bộ dữ liệu tài khoản được chứa trong đó. Cache giữ bản sao để giảm việc lấy lại khi có thể dùng bản còn hợp lệ.~GETは取得、POSTはデータを送って処理を依頼します。利用の継続を扱うためにセッション情報やCookieを使う場合があります。Cookie、セッション、キャッシュは別の概念で、保存されるものと用途を確認します。~Thẻ giữ chỗ giúp quầy nhận ra lượt giao dịch đang tiếp tục; bản in tạm của tài liệu giúp khỏi xin lại. Nhận ra khách và lưu bản sao tài liệu là hai công việc.~受付票で継続中の手続きを識別することと、文書の写しを保存することは違います。
Thư điện tử thường qua nhiều bước: ứng dụng gửi tới máy chủ, máy chủ chuyển thư, người nhận truy cập hộp thư. SMTP phục vụ gửi và chuyển; POP3 lấy thư; IMAP thao tác với hộp thư trên máy chủ. MIME giải quyết định dạng nội dung và tệp đính kèm, không thay vai trò của SMTP. Khi đề hỏi giao thức hãy xem hành động đang là chuyển thư, lấy thư hay biểu diễn nội dung.~メールの送信・サーバ間転送はSMTP、受信の取出しはPOP3、サーバ上の管理はIMAPで扱います。MIMEは内容の形式を拡張する規格です。送受信の動作と内容形式を混同しません。~Bưu cục chuyển thư, người đến nhận thư và quy cách đóng gói phong bì là ba việc riêng. Một phong bì chứa ảnh không tự cho biết cách nhận thư.~郵便局の転送、受取方法、封筒の内容形式は別の役割です。
To là người nhận chính, Cc là bản sao hiển thị, Bcc che địa chỉ đó với người nhận khác. Bcc không mã hóa nội dung, không ngăn người nhận chuyển tiếp và cũng không biến tệp đính kèm thành an toàn. Muốn bảo vệ tính bí mật và kiểm tra người ký của thư phải xét cơ chế tương ứng như S/MIME trong nguồn. NTP lại phục vụ đồng bộ thời gian, hữu ích để các bản ghi có mốc so sánh nhất quán.~To、Cc、Bccは宛先の扱いです。Bccは本文暗号化や転送禁止ではありません。メールの暗号化や署名には別の技術を使います。NTPは時刻同期であり、ログの時刻をそろえるなどに使います。~Giấu danh sách người được phát bản sao không phải niêm phong nội dung lá thư. Hai nhu cầu “ai thấy địa chỉ” và “ai đọc nội dung” cần tách rõ.~配布先の名簿を見せないことと、本文を封印することは別です。
'''
NOTES[23] = '''
Một file không chỉ là phần nội dung nhìn thấy trong trình soạn thảo: hệ thống còn phải biết tên, vị trí và cách tìm dữ liệu đó. Thư mục tổ chức các tên theo cây để hàng nghìn file không nằm chung một chỗ. Bắt đầu ở gốc, đi qua từng thư mục con rồi mới đến file; vì vậy hai file cùng tên vẫn có thể khác nhau nếu nằm ở hai nhánh khác nhau.~ファイルを利用するには内容だけでなく名前と保存場所も必要です。ディレクトリは名前を木構造で整理します。ルートから下位へたどるので、同名のファイルでも所属するディレクトリが違えば別の対象です。~Tủ hồ sơ là cây thư mục, các ngăn là thư mục con và tờ hồ sơ là file. Tên tờ giấy chưa đủ: phải biết nó ở ngăn nào. Ví von này chỉ nói về tổ chức, không phải cách các byte được đặt liên tục trên đĩa.~書庫の棚をディレクトリ、書類をファイルに例えると、書類名だけでなく棚の場所も必要です。これは整理方法の例えで、ディスク上の物理配置とは別です。
Đường dẫn tuyệt đối trả lời “đi từ gốc đến đâu?”, còn đường dẫn tương đối trả lời “từ chỗ đang đứng đi thế nào?”. Với đường tương đối phải xác định thư mục hiện tại trước: dấu `.` giữ nguyên vị trí, `..` đi lên đúng một cấp. Nếu bỏ qua mốc hiện tại, cùng chuỗi `../note.txt` sẽ bị hiểu thành nhiều file khác nhau; đây là lý do không thể giải bài đường dẫn chỉ bằng nhìn tên cuối.~絶対パスはルートを基準にし、相対パスは現在のディレクトリを基準にします。`.`は現在位置、`..`は一つ上です。相対パスは現在位置を確認してから順に解釈しなければ参照先を決められません。~“Từ cổng trường vào phòng 203” giống đường tuyệt đối; “từ phòng đang đứng lên một tầng” giống đường tương đối. Đổi điểm xuất phát sẽ đổi nơi đến của chỉ dẫn tương đối.~校門からの道順が絶対パス、今いる部屋からの道順が相対パスに相当します。相対的な道順は出発点が変わると行き先も変わります。
Sao lưu không chỉ là “có một bản mới nhất”. Full giữ toàn bộ dữ liệu ở mốc đó; differential giữ phần thay đổi kể từ full; incremental giữ phần thay đổi kể từ lần sao lưu trước. Vì mốc so sánh khác nhau, tập bản sao cần cho phục hồi cũng khác nhau. Hãy vẽ trục thời gian và ghi từng bản phụ thuộc vào đâu trước khi chọn đáp án, thay vì chỉ nhớ incremental nhỏ hơn differential.~全体保存、全体保存からの差分、直前の保存からの増分では比較する基準が違います。そのため復旧に必要な保存データも異なります。保存時点を時間順に並べ、どの時点に依存するかを確認して判断します。~Full là chụp cả bộ hồ sơ; differential là ghi mọi thay đổi từ lần chụp lớn; incremental là ghi thay đổi từ tờ ghi gần nhất. Muốn dựng lại hồ sơ phải đủ các phần cần thiết, không chỉ cầm tờ cuối.~全体の写真、写真以後の変更記録、直前以後の変更記録と考えると、復元に必要な記録の違いが分かります。
Khi phục hồi, cần phân biệt đích muốn quay về với các bản sao đang có. Với chuỗi incremental phải đi từ full qua từng mắt xích đến đích; thiếu một mắt xích có thể không dựng được trạng thái mong muốn. Bản sao tồn tại cũng chưa chứng minh có thể dùng được: cần kiểm tra quá trình phục hồi. RAID giúp duy trì hoạt động khi một số ổ hỏng theo cấu hình, nhưng không tự đưa file bị xóa nhầm trở về quá khứ.~増分で復旧する場合は全体保存から目的時点までの系列をそろえます。保存した事実だけでなく復元できることの確認も重要です。RAIDによる冗長化と、削除前の状態へ戻すためのバックアップは役割が異なります。~Một bộ hồ sơ dự phòng bị thiếu trang vẫn không giúp dựng lại đầy đủ. Có thêm người giữ cùng bản hồ sơ hiện tại cũng không thay thế bản chụp trước khi xóa nhầm.~予備の書類でも必要なページが欠ければ復元できません。現在の複製と過去の保存記録は役割が違います。
'''
NOTES[25] = '''
Giao diện tốt bắt đầu từ việc người dùng muốn làm, rồi mới chọn nút hay ô nhập. GUI dùng biểu tượng và thành phần đồ họa; CUI dùng lệnh ký tự, nhưng không thể kết luận GUI luôn dễ hơn cho mọi tác vụ. Người mới cần nhận ra lựa chọn; người thao tác lặp lại có thể cần cách làm nhanh. Khi thiết kế một màn hình, hãy xác định ai dùng, dùng trong hoàn cảnh nào và kết quả cần đạt.~画面部品を選ぶ前に、利用者、利用状況、達成したい作業を確認します。GUIは図形を、CUIは文字コマンドを使いますが、どちらが適するかは作業によって異なります。~Bảng điều khiển thang máy giúp người mới nhìn ra tầng cần chọn; một chuỗi phím tắt lại hợp với người đã quen. Sự quen thuộc của người thiết kế không đại diện cho mọi người dùng.~エレベーターの表示は初めての人を助け、慣れた人には短い操作が役立ちます。設計者の慣れを全利用者の慣れと考えないことが大切です。
Ba mặt của usability trả lời ba câu khác nhau: người dùng có làm **đúng và đủ** không, phải tốn **bao nhiêu nguồn lực**, và **cảm nhận thế nào**. Một màn hình rất nhanh nhưng thường nhập nhầm chưa chắc tốt; một màn hình hoàn thành đúng nhưng khiến người dùng mất quá nhiều bước cũng có vấn đề. Cần đánh giá trong cùng tác vụ và bối cảnh, không gộp tất cả thành một nhận xét “đẹp”.~有効さは正しく完全に達成できるか、効率はそのための資源、満足は利用者の受け止め方です。速さだけで使いやすさを決めず、同じ作業と状況でそれぞれを確認します。~Đặt món nhanh nhưng luôn nhận sai món là thất bại về kết quả; nhận đúng món sau quá nhiều thao tác là vấn đề về công sức. Hai lỗi này cần cách sửa khác nhau.~注文が速くても料理が違えば有効さの問題、正しくても操作が多すぎれば効率の問題です。
Muốn biết người dùng vấp ở đâu, hãy cho họ thực hiện một nhiệm vụ và quan sát thay vì chỉ hỏi “có dễ dùng không?”. Usability test cho thấy hành vi thực tế; đánh giá heuristic dùng chuyên gia và nguyên tắc để phát hiện vấn đề; log cho thấy xu hướng của nhiều lượt sử dụng. Mỗi cách nhìn được một phần khác nhau: nhiều lượt bấm ở một nút chưa tự chứng minh nút đó khó hiểu nếu chưa biết mục tiêu của người bấm.~ユーザーテストは実際の操作を観察し、ヒューリスティック評価は専門家が原則に照らして確認し、ログ分析は利用傾向を調べます。記録上の数値だけでは利用者の意図まで分からないことに注意します。~Quan sát một người tìm cửa ra, nhờ chuyên gia xem biển chỉ dẫn và xem luồng người qua cửa là ba nguồn thông tin bổ sung nhau; không nguồn nào tự trả lời mọi câu hỏi.~出口探しの観察、専門家による案内の点検、人の流れの記録は、それぞれ異なる手掛かりを与えます。
Chọn thành phần nhập phải phản ánh đúng quy tắc dữ liệu: một phương thức thanh toán dùng radio; các tùy chọn độc lập dùng checkbox. Sau đó hỗ trợ phòng và sửa lỗi: chỉ rõ khuôn dạng, báo lỗi gần vị trí cần sửa và cho phép hoàn tác khi phù hợp. Accessibility còn yêu cầu người dùng bàn phím hoặc công nghệ hỗ trợ tiếp cận được thao tác; màu đỏ đơn độc không đủ để truyền đạt lỗi cho mọi người.~排他的な一択にはラジオボタン、独立した複数選択にはチェックボックスを使います。入力条件、修正しやすいエラー表示、必要な取消しも検討します。キーボードや支援技術でも扱えるようにし、色だけに意味を任せません。~Một cửa chỉ cho chọn một lối đi khác với danh sách đồ mang theo có thể chọn nhiều món. Đánh dấu hình dạng và lời nhắc giúp cả người không phân biệt được màu.~一つだけ通る入口と、複数持てる持ち物の一覧は選択の意味が違います。色に加え文字や形も使うと情報を伝えやすくなります。
'''
NOTES[26] = '''
Máy tính lưu con số, còn âm thanh ngoài đời biến đổi liên tục. PCM nối hai thế giới bằng ba bước: lấy mẫu quyết định **đo lúc nào**, lượng tử hóa quyết định **làm tròn về mức nào**, mã hóa quyết định **viết mức đó thành bit ra sao**. Đảo thứ tự hoặc nhầm tần số lấy mẫu với số bit/mẫu sẽ làm sai cả cách hiểu lẫn bài tính. Hãy theo dõi một giá trị biên độ qua đủ ba bước.~PCMは、時間ごとに標本を取り、振幅を離散的な段階へ対応させ、その値をビット列にします。標本化は時間、量子化は振幅の段階、符号化は表現方法の問題として区別します。~Quay đồng hồ bằng nhiều ảnh là lấy mẫu theo thời gian; làm tròn số đo tới các vạch có sẵn giống lượng tử hóa. Đây là ví von cho việc đo, không phải âm thanh thực sự được lưu bằng ảnh.~時計を一定間隔で撮ることが時間方向の標本化、測定値を目盛りへ丸めることが量子化に似ています。音を写真で保存するという意味ではありません。
Tần số mẫu tăng thì mỗi giây có nhiều số đo hơn; bit/mẫu tăng thì mỗi số đo có nhiều mức biểu diễn hơn. Hai thay đổi giải quyết hai giới hạn khác nhau nhưng đều làm dữ liệu tăng. Kênh âm thanh cũng phải tính riêng: stereo có hai kênh trong mô hình bài học. Vì Hz là số mẫu mỗi giây, khi nhân thêm số giây thì đơn vị thời gian triệt tiêu, còn số mẫu để đổi thành bit và byte.~標本化周波数を上げると一秒の標本数が増え、量子化ビット数を増やすと振幅の段階が増えます。チャネル数と秒数も掛け、ビットからバイトへは8で割ります。単位を追うと式の意味を確認できます。~Chụp ảnh thường xuyên hơn khác với ghi mỗi số đo bằng nhiều chữ số hơn. Cả hai đều làm sổ ghi dày lên, nhưng không thay thế được nhau.~測る回数を増やすことと、一回の値を細かく記録することは別です。どちらも記録量を増やします。
Ảnh bitmap giữ thông tin theo lưới pixel; biểu diễn đường viền giữ hình dạng bằng tọa độ và đường cong rồi rasterize khi hiển thị. Vì vậy phóng to một lưới cố định có thể thấy bậc thang, trong khi đường viền có thể được tính lại theo kích thước mới. Với ảnh không nén, dung lượng phụ thuộc số pixel và bit/pixel; DPI nói về mật độ khi đặt lên kích thước vật lý, không tự cho biết toàn bộ số pixel nếu chưa biết chiều dài.~ビットマップは画素の格子を保存し、輪郭表現は曲線や座標を表示用の画素へ変換します。非圧縮画像は画素数と画素当たりのビット数で容量を求めます。DPIだけでは画像全体の画素数は決まりません。~Tranh ghép ô vuông giống bitmap; bản hướng dẫn vẽ đường cong giống outline. Phóng tờ giấy ghép ô không tự tạo thêm chi tiết đã mất.~モザイクがビットマップ、曲線の描き方がアウトラインの例です。格子を大きくしても元にない細部は増えません。
Nén khả nghịch yêu cầu giải nén trả lại đúng dữ liệu ban đầu; nén bất khả nghịch chấp nhận bỏ thông tin để đổi lấy dung lượng nhỏ hơn. Phân biệt **dữ liệu phục hồi chính xác** với **cảm giác nhìn/nghe gần giống**: một bức ảnh trông tương tự chưa chứng minh từng bit giống nhau. Video còn gồm nhiều khung theo thời gian, nên bài tính thô cần nhân số khung mỗi giây và thời lượng trước khi áp dụng tỷ lệ nén được đề cho.~可逆圧縮は元のデータを完全に戻し、非可逆圧縮は情報の一部を失います。見た目が近いこととビット列の一致は別です。動画の非圧縮量は一画面の量に毎秒の画面数と時間を掛けて考えます。~Rút gọn bản ghi bằng quy tắc có thể khôi phục đầy đủ khác với bỏ bớt chi tiết vì cho rằng không cần. Đã bỏ chi tiết thì không thể đòi giải nén tự đoán đúng bản gốc.~規則で短くして完全に戻す方法と、不要と判断した細部を捨てる方法は違います。捨てた情報は展開で必ず元に戻るわけではありません。
'''
NOTES[29] = '''
Một bảng tính có thể lưu dữ liệu, nhưng khi nhiều người cùng tra cứu và cập nhật, cần thêm quy tắc thống nhất. DBMS quản lý cách lưu, tìm và bảo vệ dữ liệu; mô hình quan hệ tổ chức dữ liệu thành bảng. Đừng nhầm hàng với loại đối tượng: bảng Customer mô tả một loại thực thể, mỗi hàng là một khách cụ thể, cột là một thuộc tính. Thứ tự hàng không phải danh tính của khách.~複数人で検索・更新するデータには一貫した管理が必要です。関係モデルでは表で整理し、行は具体的な対象、列は属性です。行の表示位置を対象の識別子と考えないようにします。~Sổ danh bạ có nhiều người, mỗi dòng là một người và các cột là tên, điện thoại. Nhưng lật sang trang khác hay sắp xếp lại sổ không làm người đó thành người khác.~名簿の一行が一人、一列が一つの属性です。並べ替えて行の位置が変わっても、同じ人であることは変わりません。
Khóa dùng để phân biệt các hàng theo quy tắc dữ liệu. Một tập thuộc tính phân biệt duy nhất là superkey; khi bỏ bớt thuộc tính nào cũng mất khả năng đó thì là candidate key. Chọn một candidate key làm primary key; vì vậy “có mã” chưa đủ, phải kiểm tra mã có duy nhất và phù hợp không. Khóa ngoại liên kết sang bảng khác, còn bản thân nó có thể lặp vì nhiều đơn hàng cùng thuộc một khách.~行を一意に識別できる属性集合がスーパーキーで、余分な属性を除いたものが候補キーです。その中から主キーを選びます。外部キーは別の表との対応に使い、多数の注文が同じ顧客を参照する場合などには値が繰り返されます。~Số thẻ thư viện giúp phân biệt bạn đọc. Nhiều phiếu mượn cùng ghi một số thẻ không làm số thẻ mất ý nghĩa: chúng đang cùng chỉ về một người.~利用者番号は一人を識別し、複数の貸出票に同じ番号が書かれていても不自然ではありません。
Toàn vẹn thực thể giữ danh tính hàng hợp lệ; toàn vẹn tham chiếu giữ mối nối giữa các bảng hợp lệ. Nếu Order.CustomerID trỏ tới C01 thì bảng Customer phải có khách C01, trừ trường hợp giá trị trống được thiết kế cho phép. Xóa khách đang được tham chiếu cần chính sách rõ ràng; không thể vừa xóa tùy tiện vừa kỳ vọng mọi đơn vẫn có chủ. Ràng buộc giúp chặn lỗi ngay lúc dữ liệu thay đổi.~主キーの規則は行の識別を守り、参照整合性は表どうしの対応を守ります。注文が顧客C01を参照するなら、その顧客が存在する必要があります。参照中の行の削除には明確な取扱いが必要です。~Phiếu mượn ghi một số thẻ chưa từng cấp là mối nối bị đứt. Không phải cứ viết được một chuỗi số lên phiếu là đã có bạn đọc thật.~未発行の利用者番号が貸出票にあれば対応が切れています。番号を書けることと相手が存在することは別です。
E-R giúp quyết định **cần lưu những đối tượng nào và chúng liên hệ ra sao** trước khi chọn cách viết truy vấn. Quan hệ một–nhiều thường được hiện thực bằng khóa ngoại ở phía nhiều; nhiều–nhiều cần bảng liên kết khi chuyển sang bảng quan hệ. Sau thiết kế mới dùng các phép chọn hàng, chiếu cột và kết nối để tạo kết quả cần xem. Một phép JOIN ghép theo điều kiện, không tự hiểu ý nghĩa nghiệp vụ nếu điều kiện viết sai.~E-Rは対象と関係を整理する設計の道具です。一対多では多側の外部キー、多対多では対応表が必要になります。検索時には行の選択、列の射影、表の結合を使いますが、結合条件は業務の対応を正しく表す必要があります。~Học sinh và môn học liên hệ qua phiếu đăng ký: một học sinh học nhiều môn, một môn có nhiều học sinh. Phiếu đăng ký là nơi ghi từng cặp, không nhét cả danh sách vào một ô.~学生と科目の間に履修記録を置けば、一人の複数科目と一科目の複数学生を一組ずつ表せます。
'''
NOTES[30] = '''
Chuẩn hóa bắt đầu từ vấn đề cập nhật chứ không phải cuộc thi chia càng nhiều bảng càng tốt. Nếu tên phòng lặp theo từng nhân viên, đổi tên phòng phải sửa nhiều dòng; sửa sót sinh mâu thuẫn. Muốn biết nên tách đâu, hãy viết các phụ thuộc hàm từ quy tắc nghiệp vụ: X→Y nghĩa là với cùng X chỉ có một Y hợp lệ. Một mẫu dữ liệu tình cờ không trùng chưa đủ để khẳng định quy tắc này đúng mãi.~正規化は更新時の矛盾を減らすために行います。同じ部署名を各社員に書くと修正漏れが起きます。分解の前に業務上の関数従属を確認し、たまたま今の表で重複がないことと区別します。~Ghi địa chỉ lớp học vào từng phiếu của học sinh khiến đổi phòng phải sửa cả xấp. Tốt hơn là giữ thông tin lớp ở một nơi rồi để phiếu tham chiếu tới đó.~教室の場所を全員のカードへ書くと移転時に全枚修正が必要です。共通の情報を一か所で管理する理由を考えます。
1NF yêu cầu mỗi ô chứa một giá trị theo miền đã định, không giấu một nhóm lặp trong ô. Nhưng mỗi ô đơn trị chưa có nghĩa là dữ liệu đã hết dư thừa. Sau khi xác định khóa, 2NF xem thuộc tính không khóa có phụ thuộc vào **toàn bộ** khóa kết hợp không. Với khóa (OrderID,ProductID), ProductName chỉ cần ProductID là biết: đó là phụ thuộc vào một phần khóa, không phải hai thuộc tính cùng cần thiết.~1NFは繰返し項目を整理し各項目を単一値にします。2NFでは複合キーの一部だけで非キー属性が決まる部分従属を取り除きます。注文番号と商品番号の組がキーでも、商品名は商品番号だけで決まる点に注目します。~Một nhãn “đơn hàng + sản phẩm” dùng để nhận biết dòng mua; tên sản phẩm lại thuộc cuốn danh mục sản phẩm, không cần biết khách đã mua nó trong đơn nào.~注文と商品の組で明細を識別しても、商品名は注文ではなく商品そのものの説明です。
3NF tiếp tục tìm đường vòng: khóa xác định thuộc tính trung gian, rồi thuộc tính trung gian xác định một thuộc tính không khóa khác. Ví dụ EmployeeID→DeptID→DeptName: đổi tên phòng là chuyện của DeptID, không phải từng nhân viên. Tách Employee(EmployeeID,DeptID) và Dept(DeptID,DeptName) giữ tên phòng ở nơi thích hợp, đồng thời giữ DeptID để có thể nối lại khi cần.~3NFでは非キー属性を経由する推移的従属を整理します。社員番号から部署番号、部署番号から部署名が決まるなら、部署名は部署表へ置きます。社員表に部署番号を残すことで、必要なときに結合できます。~Hỏi “bạn thuộc lớp nào?” rồi tra “lớp đó ở phòng nào?” là hai mối quan hệ. Không cần chép tên phòng vào từng hồ sơ học sinh để bỏ bước tra cứu.~学生の所属クラスとクラスの教室は別の対応です。教室名を全学生に重複させなくても参照で分かります。
Sau khi tách, cần kiểm tra có dựng lại thông tin ban đầu đúng không, có vô tình sinh các tổ hợp không thật không. Chỉ nhìn số bảng không thể kết luận thiết kế tốt: phải xét khóa, ràng buộc và điều kiện kết nối. Trong bài FE hãy làm theo thứ tự: ghi khóa → viết phụ thuộc → xác định phụ thuộc bộ phận/bắc cầu → chọn phép tách. Cách này giải thích được đáp án thay vì đoán từ tên bảng.~分解後は正しく元の関係を再構成できるか確認します。表の数ではなくキーと従属、結合条件で判断します。キーの確認、従属の整理、部分・推移的従属の判別、分解という順に考えると根拠を説明できます。~Xé một hồ sơ thành nhiều tờ chỉ hữu ích khi các tờ còn dấu nối đúng. Nếu làm mất mã chung, ghép hồ sơ có thể gắn nhầm dữ liệu của người khác.~書類を分けるだけでなく、正しい対応番号を残すことが必要です。結び付ける手掛かりを失うと別人の書類を混ぜてしまいます。
'''
NOTES[31] = '''
Đọc một truy vấn theo ý nghĩa xử lý, không chỉ theo thứ tự chữ viết: xác định bảng nguồn, tạo các hàng kết hợp, lọc bằng WHERE, gom nhóm, lọc nhóm bằng HAVING, chọn đầu ra rồi sắp xếp. Đây là thứ tự suy luận để giải bài, không phải cam kết về cách bộ tối ưu thực thi bên trong. Khi không có GROUP BY, hãy thử viết ra các hàng còn lại sau WHERE trước khi tính SELECT.~SQLはFROM、行の絞込み、グループ化、グループの絞込み、出力という論理的な順序で考えます。これは理解のための順序で、DBMSの物理的な実行方法を固定するものではありません。まず残る行を確認します。~Nấu ăn phải lấy nguyên liệu rồi bỏ phần không dùng trước khi chia khẩu phần. Cách trình bày món trên thực đơn không phải trình tự bếp thực hiện; SQL cũng cần tách cú pháp viết và ý nghĩa xử lý.~材料の選択と下ごしらえを考えてから盛付けを決めるように、記述順と意味上の処理を分けて考えます。
GROUP BY biến nhiều hàng thành các nhóm có cùng giá trị nhóm; SUM, AVG và COUNT tổng hợp **trong mỗi nhóm**. WHERE loại từng hàng trước bước này; HAVING xét kết quả nhóm sau bước này. Nếu muốn “phòng có tổng lương trên 500”, không thể thay bằng loại nhân viên có lương dưới 500 trước khi cộng. Thay vị trí điều kiện có thể đổi tập dữ liệu và đổi đáp án.~GROUP BYは行をグループにまとめ、集計関数は各グループを計算します。WHEREは集計前の行、HAVINGは集計後のグループを絞ります。「部署合計が500超」と「各社員が500超」は別の条件です。~Lọc những tờ hóa đơn dưới một mức tiền trước khi cộng khác với cộng đủ hóa đơn từng khách rồi chọn khách có tổng cao. Cả hai đều “lọc”, nhưng lọc ở hai thời điểm khác nhau.~小額の伝票を先に除くことと、全伝票を顧客別に合計してから顧客を選ぶことは違います。
JOIN không phải đặt hai bảng cạnh nhau theo vị trí hàng. Nó tạo các cặp thỏa điều kiện: một khách có ba đơn thì thông tin khách có thể xuất hiện ở ba hàng kết quả. INNER JOIN bỏ đối tượng không tìm được cặp; LEFT JOIN giữ các hàng bên trái ngay cả khi chưa có đối tượng phải, với phần thiếu là NULL. Vì vậy cần dự đoán số cặp theo dữ liệu, không đoán số hàng bằng số hàng bảng lớn nhất.~JOINは行の位置ではなく条件で組を作ります。一人に三件の注文があれば三組になります。内部結合は対応のある組だけ、左外部結合は左側の未対応の行も残します。件数は対応関係から考えます。~Ghép khách với các phiếu mua hàng: khách có ba phiếu xuất hiện ba lần trong bảng ghép; khách chưa mua chỉ còn nếu bài yêu cầu giữ danh sách khách bên trái.~顧客と注文票を対応付けると、三枚持つ人は三組になり、注文のない人を残すかは結合方法によります。
NULL diễn tả thiếu hoặc chưa biết, không phải số 0 và cũng không phải chuỗi rỗng. COUNT(*) đếm hàng, còn COUNT(column) không đếm giá trị NULL của cột đó. Điều kiện tìm NULL phải dùng IS NULL; phép so sánh thông thường với NULL không cho kết luận đúng như số bình thường. Khi giải bài đếm, hãy đánh dấu NULL trước rồi ghi rõ đang đếm hàng hay đếm giá trị đã có.~NULLは0や空文字と同じではありません。COUNT(*)は行を数え、COUNT(列)はその列がNULLのものを数えません。NULLの検査はIS NULLを使い、通常の値と同じ比較をしないようにします。~Ba phiếu khảo sát nhưng chỉ hai phiếu ghi tuổi: số phiếu là 3, số câu trả lời tuổi là 2. Không được tự coi ô bỏ trống là tuổi 0.~三枚の回答用紙のうち年齢記入が二枚なら、用紙数は3、年齢の回答数は2です。未記入を0歳とみなしません。
'''
